  // munge of job_SubFetch.sen
  sDefinition =
    "\""
    "\\\"munged job_SubFetch.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SubFetch.sen -- Job SubFetch                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SubFetch.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch rows                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchRows ( Job_SubFetch -- <R> )\n"
    "\n"
    "  params| pJob_SubFetch |\n"
    "  0 0 0 locals| sTableNm iPhrase iSlot |\n"
    "  0 0 0 0 locals| pPlanner pBufferQueue pIndex pTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the planner, bufferQueue, phrase and slot t\n"
    "  pJob_SubFetch job_subFetch.planner@ to pPlanner\n"
    "  pJob_SubFetch job_subFetch.bufferQueue@ to pBufferQueue\n"
    "  pJob_SubFetch job_subFetch.phrase@ to iPhrase\n"
    "  pJob_SubFetch job_subFetch.slot@ to iSlot\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  pJob_SubFetch job.objectName@ to sTableNm\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the table\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push into indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  iPhrase pPlanner Planner.fetchTechnique@\n"
    "  case\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an exact select using index\n"
    "    AT_EXACT of\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.key@\n"
    "      iPhrase\n"
    "      pPlanner\n"
    "      pBufferQueue\n"
    "      iSlot\n"
    "      pIndex index.exactKey\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // lower bound select using index\n"
    "    AT_LOWER of\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.lowKey@\n"
    "      iPhrase\n"
    "      pPlanner\n"
    "      pBufferQueue\n"
    "      iSlot\n"
    "      pIndex index.lowerBound\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an upper bound select using index\n"
    "    AT_UPPER of\n"
    "\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.highKey@\n"
    "      iPhrase\n"
    "      pPlanner\n"
    "      pBufferQueue\n"
    "      iSlot\n"
    "      pIndex index.upperBound\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // a range select using index\n"
    "    AT_RANGE of\n"
    "\n"
    "      // find the index\n"
    "      iPhrase pPlanner Planner.indexNm@\n"
    "      find execute to pIndex\n"
    "\n"
    "      // now get excat key rows from index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      iPhrase pPlanner Planner.highKey@\n"
    "      iPhrase pPlanner Planner.lowKey@\n"
    "      iPhrase\n"
    "      pPlanner\n"
    "      pBufferQueue\n"
    "      iSlot\n"
    "      pIndex index.range\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // full scan (no index)\n"
    "    AT_SCAN of\n"
    "      // find the index\n"
    "      \\\"hidden\\\" find execute to pIndex\n"
    "\n"
    "      // now scan the index\n"
    "      iSlot pTable tablePtnGrabRead  //! partitionLock\n"
    "      pBufferQueue iSlot pIndex index.scan\n"
    "      iSlot pTable tablePtnDropRead\n"
    "    endof\n"
    "\n"
    "  endcase\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* SubFetch (on originating node)                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubFetch_run ( -- <R> )\n"
    "\n"
    "  0 0 locals| pTask pJob_SubFetch |\n"
    "\n"
    "  tp: SubFetch\n"
    "  \\\"SubFetch_run\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_SubFetch\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_SubFetch getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // execute fetch depending on the fetchTechnique in the planner\n"
    "  pJob_SubFetch fetchRows\n"
    "\n"
    "  // now delete the ended job\n"
    "  pJob_SubFetch job.delete\n"
    "\n"
    "  // null the job in the task\n"
    "  nullptr pTask task.job!\n"
    "\n"
    "  ddlLock::testDrop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SubFetch.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job_Cf.sen
  sDefinition =
    "\""
    "\\\"munged job_Cf.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Cf.sen -- Job Change Folder                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Cf.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cf command request                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": cf_req ( -- <R> )\n"
    "\n"
    "  0 0 0 0 locals| pCurrentFolder sFolderNm pJob_Cf pTask |\n"
    "\n"
    "  tp: cf_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_Cf\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the objectName (folderNm) from the job\n"
    "  pJob_Cf job.objectName@ to sFolderNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_Cf getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"..\\\" which will go up one folder\n"
    "\n"
    "  // pop up one folder, but not into tenants\n"
    "  sFolderNm \\\"..\\\" str.equal if\n"
    "    0 pathPick dic.name \\\"tenants\\\" str.equal not if pathDrop then\n"
    "    savePath\n"
    "    <DONE_REQ>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"~\\\" will pop folder path till it reaches /tenants\n"
    "\n"
    "  // pop up to tenants\n"
    "  sFolderNm \\\"~\\\" str.equal if\n"
    "    begin 0 pathPick dic.name \\\"tenants\\\" str.equal not while pathDrop repeat\n"
    "    savePath\n"
    "    <DONE_REQ>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"tenants\\\" will clear folder path and set to /tenants\n"
    "\n"
    "  // clear dic path and push tenants\n"
    "  sFolderNm \\\"tenants\\\" str.equal if\n"
    "    pathDropAll\n"
    "    attachmap::tenants@ execute pathPush\n"
    "    savePath\n"
    "    <DONE_REQ>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // otherwise we expect a name of a sub -folder to which we push path to\n"
    "  // push sub-folder\n"
    "  sFolderNm findInCurrent to pCurrentFolder\n"
    "  pCurrentFolder checkIsDicR35 not if pJob_Cf <ERROR_REQUEST> exit then\n"
    "  pCurrentFolder execute pathPush\n"
    "  savePath\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Cf.sen"_Stz
  ;

  vCompileConstant(sDefinition);

