    "\\\"munged copier.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* copier.sen -- table copier                                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" copier.sen\\\" .verbose\n"
    "\n"
    ": copy ( ^fromTable ^toTable )\n"
    "  drop drop\n"
    "  \\\"copy not supported\\\" .\n"
    "  false\n"
    "/*\n"
    "  swap\n"
    "  >r >r\n"
    "  // r0 ^toTable\n"
    "  // r1 ^fromtable\n"
    "\n"
    "  \\\"__sel_cursor\\\" find dup if else\n"
    "    drop \\\"__sel_cursor\\\" :selCursor\n"
    "  then\n"
    "  execute\n"
    "\n"
    "  >r\n"
    "\n"
    "  // r0 ^selCursor\n"
    "  // r1 ^toTable\n"
    "  // r2 ^fromTable\n"
    "\n"
    "  r2 r0 selCursor.table!\n"
    "\n"
    "  tx::begin >r\n"
    "  // r0 ^txCursor\n"
    "  // r1 ^selCursor\n"
    "  // r2 ^toTable\n"
    "  // r3 ^fromTable\n"
    "\n"
    "  grid::slots 0\n"
    "  do\n"
    "    // r0 partition\n"
    "    // r1 partitions\n"
    "    // r2 ^txCursor\n"
    "    // r3 ^selCursor\n"
    "    // r4 ^toTable\n"
    "    // r5 ^fromTable\n"
    "\n"
    "    I r3 selCursor.begin\n"
    "    r3 selCursor.first\n"
    "\n"
    "    begin\n"
    "      while\n"
    "      r0 r3 selCursor.get r2 r4 table.insert\n"
    "      r3 selCursor.next\n"
    "    repeat\n"
    "\n"
    "    r3 selCursor.end\n"
    "  loop\n"
    "\n"
    "  tx.commit\n"
    "\n"
    "  // r0 ^txCursor\n"
    "  // r1 ^selCursor\n"
    "  // r2 ^toTable\n"
    "  // r3 ^fromTable\n"
    "\n"
    "  rdrop rdrop rdrop rdrop\n"
    "\n"
    "  \\\"__sel_cursor\\\" find word.forget\n"
    "\n"
    "  true\n"
    " */\n"
    " ;\n"
    "\n"
    ": tableCopier\n"
    "\n"
    "  find execute   ( \\\"<to-tableNm>\\\" ^fromTable )\n"
    "\n"
    "  swap           ( ^fromTable \\\"<to-tableNm>\\\" )\n"
    "\n"
    "  :table execute ( ^fromTable ^toTable )\n"
    "\n"
    "  // swap        ( ^toTable ^fromTable )\n"
    "\n"
    "  copy if \\\"copied!\\\" . then\n"
    "\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT copier.sen"_Stz
  ;

