  // munge of job_SubTruncate.sen
  sDefinition =
    "\""
    "\\\"munged job_SubTruncate.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SubTruncate.sen -- Job SubTruncate                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SubTruncate.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* SubTruncate (on each node)                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": SubTruncate_run ( -- <R> )\n"
    "\n"
    "  0 0 locals| pJob_SubTruncate pTask |\n"
    "  0 0 0 locals| iSlot pTable sTableNm |\n"
    "  0 0 0 locals| iTrucateJobId pJob_TruncateTable pTask_TruncateTable |\n"
    "\n"
    "  tp: SubTruncate\n"
    "  \\\"SubTruncate_run\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_SubTruncate\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  //ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_SubTruncate getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  pJob_SubTruncate job.objectName@ to sTableNm\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the table\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the slot this sub truncate is supposed to work on\n"
    "  pJob_SubTruncate job_subTruncate.slot@ to iSlot\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // truncate table for iSlot\n"
    "  iSlot pTable table.truncate\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // notify the truncate job\n"
    "  pJob_SubTruncate job_SubTruncate.truncateJobId@ to iTrucateJobId\n"
    "  iTrucateJobId job.findParticipant to pJob_TruncateTable\n"
    "  pJob_TruncateTable job_truncateTable.task@ to pTask_TruncateTable\n"
    "  pTask_TruncateTable ack\n"
    "\n"
    "  // now delete the ended job\n"
    "  pJob_SubTruncate job.delete\n"
    "\n"
    "  // null the job in the task\n"
    "  nullptr pTask task.job!\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SubTruncate.sen"_Stz
  ;

