  // munge of workerModel.sen
  sDefinition =
    "\""
    "\\\"munged workerModel.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* workerModel.sen -- worker actor model                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" workerModel.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": to_CALLER  >reg0 ;\n"
    ": to_QUEUE   >reg1 ;\n"
    "\n"
    ": to_THREAD  >reg3 ;\n"
    ": to_SENDER  >reg4 ;\n"
    "\n"
    ": _CALLER    reg0 ;\n"
    ": _QUEUE     reg1 ;\n"
    "\n"
    ": _THREAD    reg3 ;\n"
    ": _SENDER    reg4 ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get queue of actor                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": findActorQueue ( \\\"<workerNm>\\\" -- queue )\n"
    "\n"
    "  \\\".queue\\\" str.cat find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get queue of actor                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": findActorTaskQueue ( \\\"<workerNm>\\\" -- pTaskQueue )\n"
    "\n"
    "  \\\".taskQueue\\\" str.cat find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get task of actor                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": findActorTask ( \\\"<workerNm>\\\" -- task )\n"
    "\n"
    "  \\\".task\\\" str.cat find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get taskset of actor                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": findActorTaskSet ( \\\"<workerNm>\\\" -- task )\n"
    "\n"
    "  \\\".taskset\\\" str.cat find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get thread of actor                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": findActorThread ( \\\"<workerNm>\\\" -- taskset )\n"
    "\n"
    "  \\\".thread\\\" str.cat find execute\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn worker by seeding its task and spawning the os thread for it         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnWorkerActor ( ... nArgs \\\"<loopNm>\\\" \\\"<jobNm>\\\" -- )\n"
    "\n"
    "  locals| jobNm | ( ... nArgs \\\"<loopNm>\\\" )\n"
    "\n"
    "  // seed the task\n"
    "  jobNm findActorTask task.seed ( )\n"
    "\n"
    "  // spawn the os thread\n"
    "  //jobNm findActorThread thread.spawn_worker ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a worker but don't spawn thread                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createWorkerActor: ( -- )\n"
    "\n"
    "  // get token from compile stream\n"
    "  token: ( s )\n"
    "\n"
    "  locals| actorNm |\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  actorNm \\\".task\\\"    str.cat :task    execute to_CALLER  // reg0 has task\n"
    "  actorNm \\\".queue\\\"   str.cat :queue   execute to_QUEUE   // reg1 has queue\n"
    "  actorNm \\\".thread\\\"  str.cat :thread  execute to_THREAD  // reg3 has thread\n"
    "\n"
    "  //AC_WORKER reg0 task.actorModel!\n"
    "  //AC_WORKER reg3 thread.actorModel!\n"
    "\n"
    "  reg.pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a worker (but don't spawn thread)                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :createWorkerActor ( \\\"<actorNm>\\\" -- \\\"<actorNm>\\\" )\n"
    "\n"
    "  locals| actorNm |\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  actorNm \\\".task\\\"    str.cat :task    execute to_CALLER  // reg0 has task\n"
    "  actorNm \\\".queue\\\"   str.cat :queue   execute to_QUEUE   // reg1 has queue\n"
    "  actorNm \\\".thread\\\"  str.cat :thread  execute to_THREAD  // reg3 has thread\n"
    "\n"
    "  //AC_WORKER reg0 task.actorModel!\n"
    "  //AC_WORKER reg3 thread.actorModel!\n"
    "\n"
    "  reg.pop\n"
    "\n"
    "  actorNm\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT workerModel.sen"_Stz
  ;

