    "  job::this locals| pJob_dropSchema |\n"
    "\n"
    "  pJob_dropSchema dropSchema.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_DropSchema.sen"_Stz
  ;

