  // munge of job__Cancel.sen
  sDefinition =
    "\""
    "\\\"munged job__Cancel.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Cancel.sen -- generic job related words                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__Cancel.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute Job__Cancel to all participants                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Cancel::distribute ( pJobOriginator -- )\n"
    "\n"
    "  //\n"
    "  // where:  On the originator node.\n"
    "  //\n"
    "\n"
    "  params| pJobOriginator |\n"
    "\n"
    "  0 locals| pJob__Cancel |\n"
    "\n"
    "  // set the no of acks expected in originator job\n"
    "  grid::nodes pJobOriginator job.acksRemaining!\n"
    "\n"
    "  // create a new Job__Cancel\n"
    "  pJobOriginator job.id@ job.newCancel to pJob__Cancel\n"
    "\n"
    "  // send job__execute to all nodes\n"
    "  grid::nodes 0\n"
    "  do\n"
    "    // set which node this task will to send to\n"
    "    I grid::node task::this task.sendNode!\n"
    "\n"
    "    // move this task through send state/queue\n"
    "    task.send\n"
    "\n"
    "    // send the cancel job\n"
    "    pJob__Cancel >socket\n"
    "  loop\n"
    "\n"
    "  // now delete the cancel job\n"
    "  pJob__Cancel job.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__Cancel on participating node                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Cancel_rcv ( -- )\n"
    "\n"
    "  //\n"
    "  // where: on the participating node\n"
    "  //\n"
    "\n"
    "  job::this locals| pJob__End |\n"
    "\n"
    "  // find the job to be executed in the participating jobs\n"
    "  pJob__End job.id@ locals| iJobId |\n"
    "  iJobId job.findParticipant locals| pJobParticipant |\n"
    "\n"
    "  // execute the cancel seed of the job on this participating node\n"
    "  pJobParticipant SEED_CAN job.spawn\n"
    "\n"
    "  delete_completed_job\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__Cancel.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job_Space.sen
  sDefinition =
    "\""
    "\\\"munged job_Space.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Space.sen -- Job Space                                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Space.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to get space in the pool (on originating node)                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": space_req ( -- <R> )\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "  tp: space_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(nodeName VARCHAR, poolSize VARCHAR, inUse VARCHAR, free VARCHAR)\\\"\n"
    "    pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get space in the pool (executed on all nodes)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": space_exe ( pJob_Space -- )\n"
    "\n"
    "  //params| pJob_Space |\n"
    "  job::this locals| pJob_Space |\n"
    "\n"
    "  CN_JOB_SPACE pJob_Space object.assertClass\n"
    "\n"
    "  \\\"GETTING SPACE on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "\n"
    "  \\\"row: ('\\\"\n"
    "  grid::thisNodeName@ str.cat\n"
    "  \\\"', '\\\" str.cat\n"
    "  2 bp::totalSpace number.magnitude str.cat\n"
    "  \\\"', '\\\" str.cat\n"
    "  2 bp::inUseSpace number.magnitude str.cat\n"
    "  \\\"', '\\\" str.cat\n"
    "  2 bp::freeSpace number.magnitude str.cat\n"
    "  \\\"')\\\" str.cat\n"
    "\n"
    "  grid::thisNode@ pJob_Space job.response!\n"
    "  1 grid::thisNode@ pJob_Space job.rowsProcessed!\n"
    "\n"
    "  pJob_Space job.notice\n"
    "\n"
    "  pJob_Space send_job__executed\n"
    "\n"
    "  nullptr task::this task.job!\n"
    "\n"
    "  <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": space_beg ( -- )\n"
    "\n"
    "  job::this locals| pJob_space |\n"
    "\n"
    "  pJob_space job.beginParticipant\n"
    "\n"
    "  job::participantBegun\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": space_end ( -- )\n"
    "\n"
    "  \\\">> space_end <<\\\" .\n"
    "\n"
    "  job::participantEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": space_can ( -- )\n"
    "\n"
    "  \\\">> space_can <<\\\" .\n"
    "\n"
    "  job::participantCancelled\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_Space.sen"_Stz
  ;

