  // munge of plan.sen
  sDefinition =
    "\""
    "\\\"munged plan.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* plan.sen -- plan related words                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" plan.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* unpack job and enque on operator queue                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": enqueOnOp ( <<job>> taskNm -- true )\n"
    "\n"
    "tp: enqueOnOp\n"
    "\n"
    "  locals| op.task | ( <<job>> )\n"
    "\n"
    "  // find task and put job onto its jobQueue\n"
    "  op.task find execute >jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to enque job on operator queue                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addEnqueOnOp ( valset taskNm -- valset )\n"
    "\n"
    "tp: addEnqueOnOp\n"
    "\n"
    "  \\\"enqueOnOp\\\" ( valset taskNm \\\"enqueOnOp\\\" )\n"
    "\n"
    "tp: addingEnqueOnOp\n"
    "\n"
    "  >> ( valset )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pipe to job queue on same node                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>jobQueue_sameNode ( << [ rb true | false ] profile planId op.task -- )\n"
    "\n"
    "  //\\\"same node\\\" .\n"
    "\n"
    "  locals| op.task | ( << [ rb true | false ] profile planId )\n"
    "\n"
    "  // convert job to valset\n"
    "  >>\n"
    "\n"
    "  // find task and put onto it's job queue\n"
    "\n"
    "  op.task find execute >jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pipe to job queue on other node                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>jobQueue_otherNode ( << [ rb true | false ] profile planId op.task nodeNo -- )\n"
    "\n"
    "tp: >>jobQueue_otherNode\n"
    "\n"
    "  //\\\"other node\\\" .\n"
    "\n"
    "  locals| nodeNo op.task | ( << [ rb true | false ] profile plan )\n"
    "\n"
    "  //nodeNo \\\"jobQueue_otherNode NODE %V\\\" str.format .\n"
    "\n"
    "  // translate plan to planId\n"
    "  //plan.id@ ( << [ rb true | false ] profile planId )\n"
    "\n"
    "  // convert job to valset\n"
    "  >>\n"
    "\n"
    "  // add enqueOnOp which has op.task as a parameter\n"
    "  op.task addEnqueOnOp ( <<call>> )\n"
    "\n"
    "  // get sender task\n"
    "  nodeNo senderTasks @ ( <<call>> task )\n"
    "\n"
    "  // put on senders job queue\n"
    "  >jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* network aware pipe                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>jobQueue ( << [ rb true | false ] pSeitf profile planId op.task -- )\n"
    "\n"
    "  // << false profile plan op.task\n"
    "\n"
    "  // record the op.task\n"
    "  locals| op.task | ( << [ rb true | false ] profile planId )\n"
    "\n"
    "  // partition\n"
    "  0 0 \\\"\\\" locals| profile partitionId nodeNo |\n"
    "\n"
    "\n"
    "  // the profile contains partition information\n"
    "  over to profile\n"
    "\n"
    "  //dup >str \\\"PLANID %v\\\" str.format .\n"
    "  dup locals| planId |\n"
    "\n"
    "  profile str.tailInt\n"
    "  if\n"
    "    // profile has a #partitionId\n"
    "\n"
    "    to partitionId\n"
    "    partitionId grid::toNode to nodeNo\n"
    "\n"
    "    //nodeNo partitionId profile \\\"Profile %v: partition %v on node %v\\\" str.format .\n"
    "\n"
    "    nodeNo grid::thisNode@ ==\n"
    "    if\n"
    "      op.task >>jobQueue_sameNode\n"
    "    else\n"
    "      op.task nodeNo >>jobQueue_otherNode\n"
    "    then\n"
    "\n"
    "  else\n"
    "    // profile is # only\n"
    "\n"
    "    //profile \\\"Profile %v: on originating node\\\" str.format .\n"
    "    planId ho16 to nodeNo\n"
    "    //nodeNo >str \\\"node %v\\\" str.format .\n"
    "    grid::thisNode@ nodeNo ==\n"
    "    if\n"
    "      op.task >>jobQueue_sameNode\n"
    "    else\n"
    "      op.task nodeNo >>jobQueue_otherNode\n"
    "    then\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* compile the plan                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": compilePlan ( plan -- )\n"
    "\n"
    "  dup task::this task.plan!\n"
    "\n"
    "  dup ( plan plan )\n"
    "\n"
    "  plan.dic task::this task.dicStack dicStack.push ( plan )\n"
    "  //pathDump\n"
    "\n"
    "  //plan.lambda@ .\n"
    "  plan.lambda@ >:\n"
    "\n"
    "  task::this task.dicStack dicStack.drop\n"
    "\n"
    "  0 task::this task.plan!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the plan                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": executeDexPlan ( nextOp plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  0 locals| pSeitf thePlan sNextOp |\n"
    "\n"
    "  // trigger triggerOp by piping the plan to it\n"
    "  //<< \\\"triggerOp\\\" thePlan >>\n"
    "  //\\\"triggerOp.task\\\" find execute >jobQueue\n"
    "\n"
    "  task::this task.seitf@ to pSeitf\n"
    "  << pSeitf \\\"triggerScanOp\\\" thePlan plan.id@ \\\"triggerScanOp.task\\\" >>jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the plan                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": executeDfetchPlan ( nextOp plan -- )\n"
    "\n"
    "tp: executeDfetchPlan\n"
    "\n"
    "  // record the plan and profile\n"
    "  0 locals| pSeitf thePlan sNextOp |\n"
    "\n"
    "  // trigger triggerOp by piping the plan to it\n"
    "  //<< \\\"triggerOp\\\" thePlan >>\n"
    "  //\\\"triggerOp.task\\\" find execute >jobQueue\n"
    "\n"
    "  task::this task.seitf@ to pSeitf\n"
    "  pSeitf >str \\\"dfetch request tasks seitf : %v\\\" str.format .\n"
    "\n"
    "  //grid::partitions >str \\\"setting nLastBuffers to %v\\\" str.format .\n"
    "  grid::partitions pSeitf seitf.lastBuffers!\n"
    "\n"
    "  << pSeitf \\\"triggerRangeOp\\\" thePlan plan.id@ \\\"triggerRangeOp.task\\\" >>jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute plan (multi-node version)                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": distributePlan allParticipants 1 checkResult ( plan -- true n# true )\n"
    "\n"
    "tp: distributePlan\n"
    "\n"
    "  locals| thePlan |\n"
    "\n"
    "  // add plan to plan list\n"
    "  thePlan planList::addPlan\n"
    "\n"
    "tp: distPlanDone\n"
    "\n"
    "  //\\\"NODE %V\\\" grid::thisNodeName@ str.format .\n"
    "\n"
    "  //planList::show\n"
    "\n"
    "  // compile the plan\n"
    "  thePlan compilePlan\n"
    "\n"
    "tp: cplPlanDone\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* reap plan on all nodes                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": reapPlan allParticipants 1 checkResult ( ??? -- true n# true )\n"
    "\n"
    "tp: reapPlan\n"
    "\n"
    "  \\\": reapPlan\\\" .\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT plan.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of Op_mark.sen
  sDefinition =
    "\""
    "\\\"munged Op_mark.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* Op_mark.sen -- mark operator                                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" Op_mark.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* mark operator                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": markOp operator\n"
    "\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT Op_mark.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of column.sen
  sDefinition =
    "\""
    "\\\"munged column.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* column.sen -- column related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" column.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* column is used as a kind of word to identify index columns                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": column: ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make the tables columns sub folder                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeColumns ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  find execute ( dic )\n"
    "  table.subDic pathPush \\\"columns\\\" :dic drop pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within table columns folder                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinColumns\n"
    "    0 pathPick dic.name \\\"columns\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table column folder and push it onto task dictionary              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInColumns\n"
    "    withinColumns if true exit then\n"
    "    EC_NOT_IN_COLUMNS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table column folder and push it onto task dictionary              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushColumns ( -- )\n"
    "    \\\"columns\\\" checkIsWord\n"
    "    not if EC_NO_COLUMNS_DIC false exit then\n"
    "    execute pathPush\n"
    "    true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table column folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popColumns\n"
    "    pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create table column as a constant                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :column ( \\\"<columnType>\\\" \\\"<columnName>\\\" )\n"
    "    :constant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check and add a table column                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAddColumn ( \\\"<columnName>\\\" \\\"<tableNm>\\\" -- true | eEC false )\n"
    "\n"
    "  locals| tableNm columnNm |\n"
    "\n"
    "  tableNm checkInTable not if false exit then\n"
    "\n"
    "  tableNm\n"
    "  pushTableSub   assert // not if false exit then\n"
    "\n"
    "  columnNm\n"
    "  pushColumns assert // not if false exit then\n"
    "\n"
    "  // column should not already exist\n"
    "  findInCurrent\n"
    "  if EC_DUPLICATE_COLUMN false popColumns popTable exit then\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of a table                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": listColumns ( -- )\n"
    "\n"
    "  0 locals| count |\n"
    "\n"
    "  pushTableSub  assert\n"
    "  pushColumns   assert\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"\\\"                             // initial ls string\n"
    "    0 pathPick dic.lastWord        // get last word of current dic\n"
    "    dup                            // setup iteration of words\n"
    "    iterate                        //\n"
    "\n"
    "      1 count + to count\n"
    "\n"
    "      object@ word.name            // column name\n"
    "\n"
    "      \\\"row: ('\\\" swap str.cat\n"
    "      \\\" \\\" str.cat\n"
    "      object@ execute str.cat       // column type\n"
    "\n"
    "      swap\n"
    "\n"
    "      \\\"')\\\\n\\\" str.prepend            //\n"
    "\n"
    "      str.cat                       // append column to ls\n"
    "\n"
    "      object@ word.prev object!     // step backwards thru words\n"
    "\n"
    "    next                            //\n"
    "    count task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  else\n"
    "    \\\"\\\"                               // initial ls string\n"
    "    0 pathPick dic.lastWord          // get last word of current dic\n"
    "      dup                            // setup iteration of words\n"
    "      iterate                        //\n"
    "\n"
    "      object@ word.name            // column name\n"
    "\n"
    "      \\\" \\\" str.cat\n"
    "      object@ execute str.cat       // column type\n"
    "\n"
    "      swap\n"
    "\n"
    "      dup str.length\n"
    "      if \\\" , \\\" str.prepend then     //\n"
    "\n"
    "      str.cat                       // append column to ls\n"
    "\n"
    "      object@ word.prev object!     // step backwards thru words\n"
    "\n"
    "    next                            //\n"
    "\n"
    "  then\n"
    "\n"
    "  //\\\"\\\\n\\\" str.cat\n"
    "\n"
    "  popColumns\n"
    "  popTableSub\n"
    " ;\n"
    "*/\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add a column (run by all participants)                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addColumn allParticipants 3 checkResult ( \\\"<columnType>\\\" \\\"<columnNm>\\\" \\\"<tableNm>\\\" -- <result> )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"ADDING COLUMN \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tp: addingColumn\n"
    "  pushTableSub   assert // not if false exit then\n"
    "\n"
    "  pushColumns assert // not if false exit then\n"
    "\n"
    "  :column\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the column vector of the table                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": columnVecTable allParticipants 1 checkResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "  0 locals| tablePtr tableNm |\n"
    "\n"
    "  //\\\"columnVecTable\\\" . tableNm .\n"
    "\n"
    "  // get table ptr\n"
    "  tableNm find execute to tablePtr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // double check we can see the table\n"
    "  //tableNm find execute stk drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // push the table sub dic and then the columns sub dic\n"
    "  tableNm pushTableSub  assert\n"
    "  pushColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicStack.dump\n"
    "\n"
    "  // iterate contents of columns dictionary \n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    tablePtr                     ( value wordNm ^table )\n"
    "    table.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //tablePtr table.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  // push the partition sub dic and then the columns sub dic\n"
    "  tableNm pushPartitionSub assert\n"
    "\n"
    "  pushPartitionColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicStack.dump\n"
    "\n"
    "  // iterate contents of columns dictionary\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "  object@ execute              ( value )\n"
    "  object@ word.name            ( value wordNm )\n"
    "  tablePtr                     ( value wordNm ^table )\n"
    "  table.slots slots.createColumnVec\n"
    "  object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //indexPtr index.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popPartitionColumns\n"
    "\n"
    "  popPartitionSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the column vector of the table                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": columnVecTableR35 ( \\\"<tableNm>\\\" )\n"
    "\n"
    "  0 locals| tablePtr tableNm |\n"
    " assert::stack_0\n"
    "  //\\\"columnVecTable\\\" . tableNm .\n"
    "\n"
    "  // get table ptr\n"
    "  tableNm find execute to tablePtr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // double check we can see the table\n"
    "  //tableNm find execute stk drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // push the table sub dic and then the columns sub dic\n"
    "  tableNm pushTableSub  assert\n"
    "  pushColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicStack.dump\n"
    "\n"
    "  // iterate contents of columns dictionary\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    tablePtr                     ( value wordNm ^table )\n"
    "    table.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //tablePtr table.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  // push the partition sub dic and then the columns sub dic\n"
    "  tableNm pushPartitionSub assert\n"
    "\n"
    "  pushPartitionColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicStack.dump\n"
    "\n"
    "  // iterate contents of columns dictionary\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    tablePtr                     ( value wordNm ^table )\n"
    "    table.slots slots.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //indexPtr index.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popPartitionColumns\n"
    "\n"
    "  popPartitionSub\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT column.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of Op_triggerRange.sen
  sDefinition =
    "\""
    "\\\"munged Op_triggerRange.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* Op_triggerRange.sen -- flow trigger operator                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" Op_triggerRange.sen\\\" .verbose\n"
    "common/ triggerRange rbCrs /\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* trigger                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": triggerRangePlan ( profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile |\n"
    "  0 locals| partitionId |\n"
    "\n"
    "  //thePlan plan.id@ \\\"Triggering plan: %v\\\" str.format .\n"
    "\n"
    "  // trigger scanOp by piping the plan to it\n"
    "  grid::partitions 0 do\n"
    "\n"
    "    // << profile plan >> -->> nextOp\n"
    "    << I \\\"rangeOp#%v\\\" str.format thePlan plan.id@ \\\"rangeOp.task\\\" >>jobQueue\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* triggerPlan_distributed                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": triggerRangePlan_distributed subDic triggerRange ( pSeitf profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  0 locals| pTablePtr thePlan profile pSeitf |\n"
    "\n"
    "  //thePlan plan.id@ \\\"Triggering plan: %v\\\" str.format .\n"
    "\n"
    "  // trigger scanOp by piping the plan to it\n"
    "  grid::partitions 0 do\n"
    "\n"
    "    // << profile plan >> -->> nextOp\n"
    "    << pSeitf I \\\"rangeOp#%v\\\" str.format thePlan plan.id@ \\\"rangeOp.task\\\" >>jobQueue\n"
    "    //<< I \\\"rangeOp#%v\\\" str.format thePlan plan.id@ \\\"rangeOp.task\\\" >>jobQueue\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* flow trigger operator loop                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": triggerRangeOp operator ( -- NEVER )\n"
    "\n"
    "  begin\n"
    "\n"
    "    depth 0 != if \\\"stack of task has grown\\\" . debug::trap then\n"
    "\n"
    "    // wait for next job\n"
    "    jobQueue> ( valset )\n"
    "\n"
    "    // unpack it\n"
    "    valset> ( nextOp profile planId nValues )\n"
    "    drop ( nextOp profile planId )\n"
    "    // find plan using planId\n"
    "    planList::findPlan ( pSeitf profile plan true )\n"
    "    assert ( pSeitf profile plan )\n"
    "\n"
    "    // trigger the plan\n"
    "    triggerRangePlan_distributed ( )\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT Op_triggerRange.sen"_Stz
  ;

  vCompileConstant(sDefinition);

