  // munge of schema.sen
  sDefinition =
    "\""
    "\\\"munged schema.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* schema.sen -- schema related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" schema.sen\\\" .verbose\n"
    "\n"
    ": schema ;\n"
    "\n"
    "//: makeSchemas pathPush \\\"schemas\\\" :dic tick folder swap execute dic.kind! pathDrop ;\n"
    "\n"
    "\n"
    ": :schema\n"
    "    :dic\n"
    "         //dup tick schema swap word.kind!\n"
    "         dup tick schema swap execute dic.kind!\n"
    " ;\n"
    "\n"
    ": withinSchemas\n"
    "    0 pathPick dic.name \\\"schemas\\\" str.equal\n"
    " ;\n"
    "\n"
    ": checkInSchemas\n"
    "    withinSchemas if true exit then\n"
    "    EC_NOT_IN_SCHEMAS false\n"
    " ;\n"
    "\n"
    ": checkIsSchema ( word )\n"
    "\n"
    "    dup word.kind@ tick folder eql not if EC_NOT_A_FOLDER false exit then\n"
    "    dup execute dic.kind@ tick schema eql if true exit then\n"
    "    EC_NOT_A_SCHEMA false\n"
    " ;\n"
    "\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a schemas folder under given named catalog                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeSchemas ( \\\"<catalogNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING SCHEMAS FOR CATALOG \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"schemas\\\"    ( dic \\\"schemas\\\" )\n"
    "  swap         ( \\\"schemas\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a schema folder (run by participant)                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": makeSchema allParticipants 1 checkResult ( \\\"<schemaNm>\\\" -- true n# true )\n"
    "\n"
    "tp: makingSchema\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING SCHEMA \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<schemaNm>\\\" )\n"
    "\n"
    "  :schema ( \\\"<schemaNm>\\\" ^schema )\n"
    "\n"
    "  drop ( \\\"<schemaNm>\\\" )\n"
    "\n"
    "  makeTables ( )\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "*/\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT schema.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of dicStack.sen
  sDefinition =
    "\""
    "\\\"munged dicStack.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* dicStack.sen -- dictionary stack related words                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" dicStack.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop top dictionary from path                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDrop ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // drop the top dictionary\n"
    "  dicStack.drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the path                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDump ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // dump the dic stack\n"
    "  dicStack.dump\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pick a dictionary from path                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathPick ( i -- dic )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // pick the dictionary from dic stack\n"
    "  dicStack.pick\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop top dictionary from path                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathPop ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // pop the top dictionary\n"
    "  dicStack.pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* push a dictionary onto path                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathPush ( dic -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // push the dictionary onto dic stack\n"
    "  dicStack.push\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get dictionary path                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathGet ( -- ... #dics )\n"
    "\n"
    "  // this word puts the dictionary path onto the stack as a series of names\n"
    "  //   ( ... \\\"<subFolderC>\\\"  \\\"<subFolderB>\\\"  \\\"<subFolderA>\\\" 3 )\n"
    "  // note: it should not push \\\"<main>\\\"\n"
    "\n"
    "  pathDepth 0 ?do\n"
    "\n"
    "    // get dictionary[I]\n"
    "    I pathPick  ( dic )\n"
    "\n"
    "    // push dictionary name\n"
    "    dic.name ( ... dicNm )\n"
    "\n"
    "  loop\n"
    "\n"
    "  // push number of dictionary names\n"
    "  pathDepth ( ... #dics )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set dictionary path                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathSet ( ... \\\"<subFolder>\\\" nFolders -- )\n"
    "\n"
    "  //dicPath.set\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words in the current dictionary                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": words\n"
    "\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ word.name .          // print the name of the word\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words (long form) in the current dictionary                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": symbols\n"
    "\n"
    "  0 pathPick dic.lastWord\n"
    "  begin dup while\n"
    "    dup word.name .put \\\" \\\" .put dup word.kind@ word.name .put .\\\\n\n"
    "    word.prev\n"
    "  repeat\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get all words in the current dictionary as a single string                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listContents ( job -- )\n"
    "\n"
    "  params| pJob |\n"
    "  0 locals| iCount |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR)\\\" pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // form the row for each word\n"
    "  \\\"\\\"                               // initial contents string\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                          // setup iteration of words\n"
    "    1 iCount + to iCount\n"
    "    \\\"row: ('\\\" str.cat\n"
    "    object@ word.name str.cat      // add name of the word to contents string\n"
    "    \\\"')\\\\n\\\" str.cat\n"
    "    object@ word.prev object!      // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in the job\n"
    "  grid::thisNode@ pJob job.response!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sent rows Processed in the job\n"
    "  iCount grid::thisNode@ pJob job.rowsProcessed!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get all words in the current dictionary as a single string (indexes)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": listIndexesContents ( -- )\n"
    "\n"
    "  0 0 locals| iCount pIndexPtr |\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, isUnique BOOLEAN, isPrimaryKey BOOLEAN)\\\" metadata!\n"
    "    \\\"\\\"                              // initial contents string\n"
    "    0 pathPick dic.lastWord dup\n"
    "    iterate                         // setup iteration of words\n"
    "\n"
    "      // get the index ptr\n"
    "      object@ word.name findInCurrent execute to pIndexPtr\n"
    "\n"
    "      // skip hidden index\n"
    "      pIndexPtr index.isHidden@ not if\n"
    "\n"
    "        // increment count\n"
    "        1 iCount + to iCount\n"
    "\n"
    "        // index a primary key ?\n"
    "        pIndexPtr index.isPrimaryKey@\n"
    "        if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "        // index is unique ?\n"
    "        pIndexPtr index.isUnique@\n"
    "        if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "        // add word kind to ls string\n"
    "        object@ word.name\n"
    "\n"
    "        \\\"row: ('%v',%v,%v)\\\\n\\\" str.format\n"
    "        str.cat\n"
    "      then\n"
    "      object@ word.prev object!       // step backwards thru words\n"
    "    next\n"
    "    iCount task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  else\n"
    "    \\\"\\\"                              // initial contents string\n"
    "\n"
    "    0 pathPick dic.wordCount locals| iCountIndexes |\n"
    "    0 pathPick dic.lastWord dup\n"
    "    iterate                         // setup iteration of words\n"
    "\n"
    "      // get the index ptr\n"
    "      object@ word.name findInCurrent execute to pIndexPtr\n"
    "\n"
    "        // increment count\n"
    "        1 iCount + to iCount\n"
    "\n"
    "        // skip hidden index\n"
    "        pIndexPtr index.isHidden@ not if\n"
    "\n"
    "          object@ word.name               // add name of the word to contents string\n"
    "          str.cat\n"
    "\n"
    "          // index is unique ?\n"
    "          pIndexPtr index.isUnique@\n"
    "          if \\\" unique\\\" str.cat then\n"
    "\n"
    "          // index a primary key ?\n"
    "          pIndexPtr index.isPrimaryKey@\n"
    "          if \\\" primary\\\" str.cat then\n"
    "\n"
    "          iCount iCountIndexes 1 - == not if \\\" , \\\" str.cat then\n"
    "\n"
    "        then\n"
    "\n"
    "        object@ word.prev object!         // step backwards thru words\n"
    "      next\n"
    "  then\n"
    "\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget all words in given dictionary                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": forgetAll ( dic -- )\n"
    "\n"
    "  dup dic.lastWord not if drop exit then\n"
    "\n"
    "  dup pathPush\n"
    "\n"
    "  begin\n"
    "\n"
    "    dup dic.lastWord word.name :forget\n"
    "\n"
    "    dup dic.lastWord not until\n"
    "\n"
    "  pathDrop\n"
    "\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a subdictionary under given dic                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :folder ( \\\"<subDicNm>\\\" dic -- )\n"
    "\n"
    "  pathPush :dic tick folder swap execute dic.kind! pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* clear task dictionary stack                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicStack.clear\n"
    "\n"
    "  pathDepth 0 ?do\n"
    "    pathDrop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop all dictionaries from given stack                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicStack.dropAll ( dicStack -- )\n"
    "\n"
    "  locals| dicStack |\n"
    "\n"
    "  dicStack dicStack.depth 0 ?do\n"
    "    dicStack dicStack.drop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set task dictionary stack                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicStack.set ( ... #dics -- )\n"
    "\n"
    "  // this word puts the folder path on the stack into task dictionary stack\n"
    "  // ( ... \\\"<subFolderC>\\\"  \\\"<subFolderB>\\\"  \\\"<subFolderA>\\\" \\\"main\\\" 4 )\n"
    "\n"
    "  tp: dicStack.set\n"
    "\n"
    "  dicStack.clear\n"
    "\n"
    "  dup not if drop exit then\n"
    "\n"
    "  0 do\n"
    "\n"
    "    dup \\\"<main>\\\" str.equal if\n"
    "      drop\n"
    "      dic.main\n"
    "      pathPush\n"
    "    else\n"
    "\n"
    "      dup \\\"seitf\\\" str.equal if\n"
    "        drop\n"
    "      else\n"
    "\n"
    "        dup \\\"tenants\\\" str.equal if\n"
    "          drop attachmap::tenants@ execute pathPush\n"
    "        else\n"
    "          find\n"
    "          execute\n"
    "          pathPush\n"
    "        then\n"
    "      then\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop top dictionary from path                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDropAll ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // drop the top dictionary\n"
    "  dicStack.dropAll\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT dicStack.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job_DropTenant.sen
  sDefinition =
    "\""
    "\\\"munged job_DropTenant.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_DropTenant.sen -- Job Drop Tenant                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_DropTenant.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable tenant folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveTenant ( \\\"<tenantNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTenantNm |\n"
    "\n"
    "  checkInTenants  not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  sTenantNm checkIsWordR35  not if EC_NO_SUCH_Tenant false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkIsTenant   not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkIsEmpty    not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkNotUsed    not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a tenant folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeTenant ( \\\"<tenantNm>\\\" --  )\n"
    "\n"
    "  tp: removetenant\n"
    "\n"
    "  args.tracepoint if\n"
    "  dup \\\"REMOVING TENANT \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  :forget ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop tenant request (on originating node)                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant_req ( -- <R> )\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "  tp: dropTenant_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_DropTenant job on a node                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant_exe ( pJob_DropTenant -- )\n"
    "\n"
    "  //params| pJob_DropTenant |\n"
    "  job::this locals| pJob_DropTenant |\n"
    "\n"
    "  tp: dropTenant_exe\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert correct job\n"
    "  CN_JOB_DROPTENANT pJob_DropTenant object.assertClass\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grad a ddl lock\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_DropTenant getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // remove the catalog\n"
    "  pJob_DropTenant job.objectName@   ( catalogNm )\n"
    "  removeTenant\n"
    "\n"
    "  pJob_DropTenant job.notice\n"
    "\n"
    "  pJob_DropTenant send_job__executed\n"
    "\n"
    "  nullptr task::this task.job!\n"
    "\n"
    "  <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_DropTenant job check resources                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant.checkResources ( Job_DropTenant -- )\n"
    "\n"
    "  params| pJob_DropTenant  |\n"
    "\n"
    "  tp: dropTenant.checkResources\n"
    "  \\\"checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - --\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_DropTenant getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we can remove the catalog\n"
    "  pJob_DropTenant job.objectName@\n"
    "  checkRemoveTenant not if pJob_DropTenant <ERROR_JOB> exit then\n"
    "\n"
    "  ddlLock::dropWrite\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_DropCatalog job release resources                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant.releaseResources ( Job_DropTenant -- )\n"
    "\n"
    "  params| pJob_DropTenant  |\n"
    "\n"
    "  tp: dropTenant.releaseResources\n"
    "  \\\"releaseResources received\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant_beg ( -- )\n"
    "\n"
    "  job::this locals| pJob_dropTenant |\n"
    "\n"
    "  pJob_dropTenant job.beginParticipant\n"
    "\n"
    "  // check resources\n"
    "  pJob_dropTenant dropTenant.checkResources\n"
    "\n"
    "  job::participantBegun\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant_end ( -- )\n"
    "\n"
    "  job::this locals| pJob_dropTenant |\n"
    "\n"
    "  pJob_dropTenant dropTenant.releaseResources\n"
    "\n"
    "  job::participantEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropTenant_can ( -- )\n"
    "\n"
    "  job::this locals| pJob_dropTenant |\n"
    "\n"
    "  // check resources\n"
    "  pJob_dropTenant dropTable.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_DropTenant.sen"_Stz
  ;

