  // munge of job_ListColumns.sen
  sDefinition =
    "\""
    "\\\"munged job_ListColumns.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_ListColumns.sen -- Job list Columns                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_ListColumns.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of a table                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listColumns ( \\\"<tableNm>\\\" Job_ListColumns -- )\n"
    "\n"
    "  params|  pJob_ListColumns sTableNm |\n"
    "\n"
    "  0 0 0 locals| pColumn iColumns pTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get table\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  pTable table.columnCount@ to iColumns\n"
    "\n"
    "  // skip the hidden column\n"
    "  iColumns 1 - to iColumns\n"
    "\n"
    "  \\\"\\\"                             // initial ls string\n"
    "  iColumns 0 do\n"
    "    I pTable table.column@ to pColumn\n"
    "    pColumn column.isPartitionKey@\n"
    "    pColumn column.isNullable@\n"
    "    pColumn column.Scale@\n"
    "    pColumn column.Length@\n"
    "    pColumn column.type@\n"
    "    pColumn column.name@\n"
    "    I\n"
    "    \\\"row: ( %v,'%v',%v,%v,%v,%v,%v )\\\\n\\\" str.format\n"
    "    str.cat\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in the job\n"
    "  grid::thisNode@ pJob_ListColumns job.response!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sent rows Processed in the job\n"
    "  iColumns grid::thisNode@ pJob_ListColumns job.rowsProcessed!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* List Columns requests (on the originating node)                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listColumns_req ( -- <R> )\n"
    "\n"
    "  0 0 0 0 locals| sTableNm iCount pJob_ListColumns pTask |\n"
    "\n"
    "  tp: listColumns_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_ListColumns\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // set dictionary stack\n"
    "  pJob_ListColumns getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab ddl read lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if pJob_ListColumns <ERROR_REQUEST> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get table name from job\n"
    "  pJob_ListColumns job.objectName@ to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if pJob_ListColumns <ERROR_REQUEST> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is a table\n"
    "  sTableNm checkIsTableR35 not if popTable pJob_ListColumns <ERROR_REQUEST> exit then\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(columnNo INTEGER, columnName VARCHAR, columnType VARCHAR, columnLength INTEGER, columnScale INTEGER, isNull boolean, isPartitionKey boolean)\\\"\n"
    "        pJob_ListColumns job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list table columns\n"
    "  sTableNm pJob_ListColumns listColumns\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "  assertInTables\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_ListColumns.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of Op_sink.sen
  sDefinition =
    "\""
    "\\\"munged Op_sink.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* Op_sink.sen -- sink operator                                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" Op_sink.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* sink the plan                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sinkPlan ( pSeitf profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile pSeitf |\n"
    "\n"
    "  thePlan planList::removePlan\n"
    "\n"
    "  //\\\"sinking plan\\\" .\n"
    "  thePlan plan.delete\n"
    "\n"
    "  //\\\"removed & deleted plan\\\" .\n"
    "  //planList::show\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* sink operator loop                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sinkOp operator ( -- NEVER )\n"
    "\n"
    "  begin\n"
    "\n"
    "    depth 0 != if \\\"stack of task has grown\\\" . debug::trap then\n"
    "\n"
    "    // wait for next job\n"
    "    jobQueue> ( valset )\n"
    "\n"
    "    // unpack it\n"
    "    valset> ( profile planId nValues )\n"
    "    drop ( profile planId )\n"
    "\n"
    "    // find plan using planId\n"
    "    planList::findPlan ( pSeitf profile plan true )\n"
    "    assert ( pSeitf profile plan )\n"
    "\n"
    "    // sink the plan\n"
    "    sinkPlan ( )\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT Op_sink.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of Op_scan.sen
  sDefinition =
    "\""
    "\\\"munged Op_scan.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* Op_scan.sen -- table scan select operator                                   */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" Op_scan.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* frame-level variables for scan                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "common/ scan rbCrs /\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* scan partition of a table                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanPartition subDic scan ( pSeitf profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile pSeitf |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set path (hardcoded for the moment)\n"
    "\n"
    "  //\\\"tables\\\" \\\"tpchSchema\\\" \\\"schemas\\\" \\\"rapidsse\\\" \\\"catalogs\\\" \\\"boray\\\" \\\"tenants\\\" 7 dicStack.set\n"
    "  \\\"tenants\\\" 1 dicStack.set\n"
    "\n"
    "  // [0] push thePlan's dictionary onto path stack\n"
    "  thePlan plan.dic pathPush\n"
    "\n"
    "  // [1] find and push opFrame (along with its dictionary onto path stack)\n"
    "  profile thePlan plan.opFrame? opFrame.push // [1]\n"
    "  //pathDump\n"
    "\n"
    "  $$tableNm   locals| tableNm   |\n"
    "  $$schemaNm  locals| schemaNm  |\n"
    "  $$catalogNm locals| catalogNm |\n"
    "\n"
    "  // drop the dictionary path\n"
    "  pathDrop\n"
    "\n"
    "  // now create the dictionary path again with the catalog and schemaNm\n"
    "  \\\"catalogs\\\" \\\"boray\\\" \\\"tenants\\\" 3 dicStack.set\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  catalogNm find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  \\\"schemas\\\" find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  schemaNm find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  \\\"tables\\\" find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm on the dictionary path\n"
    "  tableNm find execute\n"
    "  pathPush\n"
    "\n"
    "  // [0] push thePlan's dictionary onto path stack\n"
    "  thePlan plan.dic pathPush\n"
    "\n"
    "  // [1] find and push opFrame (along with its dictionary onto path stack)\n"
    "  profile thePlan plan.opFrame? opFrame.push // [1]\n"
    "\n"
    "  // [2] create a new rowCursor and record in opFrame.rbCrs\n"
    "  rbCursor::new toCommon rbCrs\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set up table in rowCursor\n"
    "  $$tableNm find execute rbCrs rbCursor.table!\n"
    "\n"
    "  // begin scan of partition\n"
    "  $$partition grid::toSlot rbCrs rbCursor.begin\n"
    "\n"
    "  // get first rowBuffer of partition\n"
    "  rbCrs rbCursor.first\n"
    "\n"
    "  // pipe all rb's of partition\n"
    "  begin while\n"
    "\n"
    "    // << rb true profile plan profile >> -->> nextOp\n"
    "    << rbCrs rbCursor.get true pSeitf $$nextProfile thePlan plan.id@ $$nextOp >>jobQueue\n"
    "\n"
    "    // next rowBuffer in partition\n"
    "    rbCrs rbCursor.next\n"
    "\n"
    "  repeat\n"
    "\n"
    "  // end cursored iteration\n"
    "  rbCrs rbCursor.end\n"
    "\n"
    "  // pipe EOD to writeOp\n"
    "  // << false plan >> -->> nextOp\n"
    "  << false pSeitf $$nextProfile thePlan plan.Id@ $$nextOp >>jobQueue\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // [2] delete cursor\n"
    "  rbCrs rbCursor.delete\n"
    "  0 toCommon rbCrs\n"
    "\n"
    "  // [1] discard opFrame (and dictionary)\n"
    "  opFrame.drop\n"
    "\n"
    "  // [0] discard thePlan's dictionary from path stack\n"
    "  // pop the plan dic as plan may have gotten deleted\n"
    "  pathPop\n"
    "\n"
    "  dicStack.clear\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* table scan operator loop                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanOp operator ( -- NEVER )\n"
    "\n"
    "  begin\n"
    "\n"
    "    depth 0 != if \\\"stack of task has grown\\\" . debug::trap then\n"
    "\n"
    "    // wait for next job\n"
    "    jobQueue> ( valset )\n"
    "\n"
    "    //grid::thisNode@ \\\"SCANOP: NODE %V\\\" str.format .\n"
    "\n"
    "    // unpack it\n"
    "    valset> ( profile planId nValues )\n"
    "    drop ( profile planId )\n"
    "\n"
    "    // find plan using planId\n"
    "    planList::findPlan ( pSeitf profile plan true )\n"
    "    assert ( pSeitf profile plan )\n"
    "\n"
    "    // scan the table partition and pipe to write\n"
    "    scanPartition ( )\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT Op_scan.sen"_Stz
  ;

  vCompileConstant(sDefinition);

