  // munge of job_SizeIndex.sen
  sDefinition =
    "\""
    "\\\"munged job_SizeIndex.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SizeIndex.sen -- Job Size Table                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SizeIndex.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a valid index                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkSizeIndex ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWordR35 not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTableR35 not if popTable false exit then\n"
    "  sTableNm tableInUse if popTable EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is an index we are dropping\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable assertInTables false exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* size index request (on originating node)                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex_req ( -- <R> )\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "  tp: sizeIndex\n"
    "  \\\"sizeIndex_req\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(nodeName VARCHAR, size VARCHAR)\\\" \n"
    "    pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeIndex job on a node                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex_exe ( Job_SizeIndex -- )\n"
    "\n"
    "  //params| pJob_SizeIndex |\n"
    "  job::this locals| pJob_SizeIndex |\n"
    "\n"
    "  0 0 0 0 locals| pIndex iSize sTableNm sIndexNm |\n"
    "\n"
    "  tp: sizeIndex_exe\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert correct job\n"
    "  CN_JOB_SIZEINDEX pJob_SizeIndex object.assertClass\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grad a ddl lock\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_SizeIndex getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table and index names\n"
    "  pJob_SizeIndex job.indexName@ to sIndexNm\n"
    "  pJob_SizeIndex job.objectName@ to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table and indexes folder\n"
    "  sTableNm pushTable assert\n"
    "  pushIndexes assert\n"
    "\n"
    "  sIndexNm find execute to pIndex\n"
    "  pIndex index.space 0 swap number.magnitude to iSize\n"
    "\n"
    "  iSize grid::thisNodeName@ \\\"row: ( %v %v )\\\" str.format\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop indexes and table folder\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  grid::thisNode@ pJob_SizeIndex job.response!\n"
    "  1 grid::thisNode@ pJob_SizeIndex job.rowsProcessed!\n"
    "\n"
    "  pJob_SizeIndex job.notice\n"
    "\n"
    "  pJob_SizeIndex send_job__executed\n"
    "\n"
    "  nullptr task::this task.job!\n"
    "\n"
    "  <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeIndex job check resources                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex.checkResources ( Job_SizeIndex -- )\n"
    "\n"
    "  params| pJob_SizeIndex  |\n"
    "  0 0 locals| sIndexNm sTableNm |\n"
    "\n"
    "  tp: sizeIndex.checkResources\n"
    "  \\\"checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set dictionary stack\n"
    "  pJob_SizeIndex getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get index and table name\n"
    "  pJob_SizeIndex job.indexName@ to sIndexNm\n"
    "  pJob_SizeIndex job.objectName@ to sTableNm\n"
    "\n"
    "  sTableNm sIndexNm checkSizeIndex not if pJob_SizeIndex <ERROR_JOB> exit then\n"
    "\n"
    "  ddlLock::dropWrite\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeTable job release resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex.releaseResources ( Job_SizeIndex -- )\n"
    "\n"
    "  params| pJob_SizeIndex  |\n"
    "\n"
    "  tp: sizeIndex.releaseResources\n"
    "  \\\"releaseResources received\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex_beg ( -- )\n"
    "\n"
    "  job::this locals| pJob_sizeIndex |\n"
    "\n"
    "  pJob_sizeIndex job.beginParticipant\n"
    "\n"
    "  // check resources\n"
    "  pJob_sizeIndex sizeIndex.checkResources\n"
    "\n"
    "  job::participantBegun\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex_end ( -- )\n"
    "\n"
    "  job::this locals| pJob_sizeIndex |\n"
    "\n"
    "  pJob_sizeIndex sizeIndex.releaseResources\n"
    "\n"
    "  job::participantEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex_can ( -- )\n"
    "\n"
    "  job::this locals| pJob_sizeIndex |\n"
    "\n"
    "  pJob_sizeIndex sizeIndex.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SizeIndex.sen"_Stz
  ;

