  // munge of job_StartCluster.sen
  sDefinition =
    "\""
    "\\\"munged job_StartCluster.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_StartCluster.sen -- Job Start Cluster                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_StartCluster.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": node.isConnected ( pNode -- t|f )\n"
    "\n"
    "  params| pNode |\n"
    "\n"
    "  pNode node.socket@ if\n"
    "    true\n"
    "  else\n"
    "    false\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::connected ( -- t|f )\n"
    "\n"
    "  grid::nodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected not if\n"
    "      I \\\"Node no %v not connected\\\" fmt.print\n"
    "      unloop\n"
    "      false\n"
    "      exit\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  \\\"All nodes connected\\\" .\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::wait ( -- )\n"
    "\n"
    "  begin\n"
    "    grid::connected not\n"
    "  while\n"
    "    100 thread.sleep_ms\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gridTest\n"
    "\n"
    "  grid::nodes 0\n"
    "  do\n"
    "    I grid::node node.isConnected\n"
    "    I \\\"gridTest: node no %v connected %v \\\" fmt.print\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gridWait\n"
    "\n"
    "  grid::wait\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to wait for cluster to start (on originating node)                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster_req ( -- <R> )\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "  tp: space_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  \\\"spawnNodes...\\\" .\n"
    "  spawnNodes\n"
    "\n"
    "  \\\"setStartNode...\\\" .\n"
    "  setStartNode\n"
    "\n"
    "  \\\"spawn_Connector...\\\" .\n"
    "  spawn_Connector\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait till all nodes connected\n"
    "  grid::wait\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute job_StartCluster (on participating node)                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster_exe ( pJob_StartCluster -- )\n"
    "\n"
    "  //params| pJob_StartCluster |\n"
    "  job::this locals| pJob_StartCluster |\n"
    "\n"
    "  pJob_StartCluster job.notice\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait till all nodes connected\n"
    "  grid::wait\n"
    "\n"
    "  pJob_StartCluster send_job__executed\n"
    "\n"
    "  nullptr task::this task.job!\n"
    "\n"
    "  <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster_beg ( -- )\n"
    "\n"
    "job::this locals| pJob_status |\n"
    "\n"
    "pJob_status job.beginParticipant\n"
    "\n"
    "job::participantBegun\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster_end ( -- )\n"
    "\n"
    "job::this locals| pJob_status |\n"
    "\n"
    "job::participantEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": startCluster_can ( -- )\n"
    "\n"
    "job::this locals| pJob_status |\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_StartCluster.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of requests_schema.sen
  sDefinition =
    "\""
    "\\\"munged requests_schema.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_schema.sen -- the set of schema related requests                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" requests_schema.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a schema                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": createSchema_req ( \\\"<schemaNm>\\\" -- <R> )\n"
    "\n"
    "  tp: createSchema\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  checkEnoughBuffers not if <NIP+ERROR> exit then\n"
    "  checkMakeSchema    not if <NIP+ERROR> exit then\n"
    "\n"
    "  makeSchema ( ) assert::stack_0\n"
    "\n"
    "  tp: createdSchema\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop a schema                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": dropSchema_req ( \\\"<schemaNm>\\\" -- <R> )\n"
    "\n"
    "  tp: dropSchema\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  checkRemoveSchema not if <NIP+ERROR> exit then\n"
    "\n"
    "  removeSchema ( ) assert::stack_0\n"
    "\n"
    "  tp: droppedSchema\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get list of schemas                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": listSchemas_req ( -- sSchemaList <R> )\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  checkInSchemas not if <NIP+ERROR> exit then\n"
    "\n"
    "  listContents\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* use given schema                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": useSchema_req ( \\\"<schemaNm>\\\" -- <R> )\n"
    "\n"
    "  tp: useSchema\n"
    "\n"
    "  // pop path till we get to tenants\n"
    "  begin\n"
    "    0 pathPick dic.name \\\"tenants\\\" str.equal not while pathDrop\n"
    "  repeat\n"
    "\n"
    "  // find the boray folder\n"
    "  \\\"boray\\\" findInCurrent\n"
    "  execute pathPush\n"
    "\n"
    "  // find the catalogs folder\n"
    "  \\\"catalogs\\\" findInCurrent\n"
    "  execute pathPush\n"
    "\n"
    "  // find the rapidssecatalogs folder\n"
    "  \\\"rapidsse\\\" findInCurrent\n"
    "  execute pathPush\n"
    "\n"
    "  // find the schemas folder\n"
    "  \\\"schemas\\\" findInCurrent\n"
    "  execute pathPush\n"
    "\n"
    "  checkIsWord   not if EC_NO_SUCH_SCHEMA <NIP+ERROR> exit then\n"
    "  checkIsSchema not if <NIP+ERROR> exit then\n"
    "  execute pathPush\n"
    "\n"
    "  // find the tables folder\n"
    "  \\\"tables\\\" findInCurrent\n"
    "  execute pathPush\n"
    "\n"
    "  tp: usingSchema\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "*/\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_schema.sen"_Stz
  ;

