    "    I 1000000 % not if I . then\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT streamLoader.sen"_Stz
  ;

