  // munge of job__Ended.sen
  sDefinition =
    "\""
    "\\\"munged job__Ended.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Ended.sen -- generic job related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__Ended.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send Job__Ended back to originating node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Ended::send ( pJobParticipant -- )\n"
    "\n"
    "  params| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.id@ locals| iJobId |\n"
    "\n"
    "  0 locals| pJob__Ended |\n"
    "\n"
    "  // new a temporary Job__Ended\n"
    "  iJobId job.newEnded to pJob__Ended\n"
    "\n"
    "  // send Job__Ended to originating node\n"
    "  iJobId job::originator@ grid::node task::this task.sendNode!\n"
    "  task.send\n"
    "\n"
    "  // send the ended job\n"
    "  pJob__Ended >socket\n"
    "\n"
    "  // delete Job__Ended\n"
    "  pJob__Ended job.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__Ended on originating node                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Ended_rcv ( -- )\n"
    "\n"
    "  job::this locals| pJob__Ended |\n"
    "  pJob__Ended job.id@ locals| iJobId |\n"
    "\n"
    "  0 0 locals| pJob iAcksRemaining |\n"
    "\n"
    "  // find the job in the originator jobs\n"
    "  iJobId job.findOriginator to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // decrement the acks remaining\n"
    "  pJob job.decAcksRemaining to iAcksRemaining\n"
    "\n"
    "  // if there are acks remaining just exit\n"
    "  iAcksRemaining 0 != if\n"
    "    delete_completed_job\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \\\"received Job__Ended from all nodes\\\" .\n"
    "\n"
    "  // remove the job from the originator jobs\n"
    "  pJob job.removeOriginator\n"
    "\n"
    "  // notify the originating task\n"
    "  pJob job.originatingTask@ ack\n"
    "\n"
    "  \\\"All Done\\\" .\n"
    "\n"
    "  delete_completed_job\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__Ended.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of grid.sen
  sDefinition =
    "\""
    "\\\"munged grid.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* grid.sen -- grid routines                                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" grid.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grid is use as a kind of word to identify grids                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": <SUCCESS_RESULT> grid::thisNode@ true ( v n# true ) ;\n"
    "\n"
    ": <FAILURE_RESULT> grid::thisNode@ false ( ec n# false ) ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check grid result                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkResult ( b n# t | ec n# f .... nn t/f )\n"
    "\n"
    "tp: checkResult\n"
    "\n"
    "  // was the final result true ?\n"
    "  true == if  ( b n# t | ec n# f .... nn )\n"
    "\n"
    "    // drop the rest of the result\n"
    "    depth dropN ( )\n"
    "\n"
    "  else\n"
    "    // lets see which node failed\n"
    "    0 do\n"
    "\n"
    "      false == if  ( ... ec n# )\n"
    "\n"
    "        swap error.msg swap\n"
    "        grid::node node.name\n"
    "        \\\"%v ERROR: %v\\\" str.format .\n"
    "\n"
    "      else\n"
    "\n"
    "        drop drop  ( ... )\n"
    "\n"
    "      then\n"
    "\n"
    "    loop\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print grid result                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": printResult ( s n# t | ec n# f .... nn t/f )\n"
    "\n"
    "tp: printResult\n"
    "\n"
    "  // was the final result true ?\n"
    "  true == if ( s n# t | ec n# f .... nn )\n"
    "\n"
    "    // pretty print the results resturned\n"
    "    0 do  ( s n# t | s n# f .... )\n"
    "\n"
    "      assert // should be true\n"
    "      grid::node node.name \\\"%v: %v\\\"  str.format .\n"
    "    loop\n"
    "\n"
    "  else\n"
    "\n"
    "    // lets see which node failed\n"
    "    0 do  ( s n# t | ec n# f .... )\n"
    "\n"
    "      false == if ( s n# t | ec n# )\n"
    "\n"
    "        swap error.msg swap\n"
    "        grid::node node.name\n"
    "        \\\"%v ERROR: %v\\\" str.format .\n"
    "\n"
    "      else\n"
    "\n"
    "        drop drop\n"
    "\n"
    "      then\n"
    "\n"
    "    loop\n"
    "\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return grid result                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": returnResult ( s n# t | ec n# f .... nn t/f )\n"
    "\n"
    "  tp: returnResult\n"
    "\n"
    "  0 0 locals| results seitf |\n"
    "\n"
    "  // get this tasks seitf\n"
    "  task::this task.seitf@ to seitf\n"
    "\n"
    "  // was the final result true ?\n"
    "  true == if ( s n# t | ec n# f .... nn )\n"
    "\n"
    "    to results\n"
    "    \n"
    "    // concatenate the results returned\n"
    "    results\n"
    "    0 do  ( s n# t | s n# f .... )\n"
    "\n"
    "      I 0 == if\n"
    "        \\\"\\\"\n"
    "      then\n"
    "\n"
    "      3 roll ( \\\" \\\" s n# t )\n"
    "\n"
    "      assert // should be true\n"
    "\n"
    "        args.metadata if\n"
    "          drop\n"
    "          \\\"\\\\n\\\" str.cat\n"
    "        else\n"
    "          grid::node node.name  ( \\\" \\\" s nodeName )\n"
    "          \\\"%v: %v\\\\n\\\" str.format\n"
    "        then\n"
    "        str.cat\n"
    "    loop\n"
    "    results seitf seitf.rowsProcessed\n"
    "    true\n"
    "  else\n"
    "\n"
    "    // lets see which node failed\n"
    "    0 do  ( s n# t | ec n# f .... )\n"
    "\n"
    "      false == if ( s n# t | ec n# )\n"
    "        //swap error.msg swap\n"
    "        //grid::node node.name\n"
    "        //\\\"error: %v %v\\\" str.format\n"
    "        drop false\n"
    "      else\n"
    "        drop drop\n"
    "      then\n"
    "\n"
    "    loop\n"
    "    // returning error\n"
    "    0 seitf seitf.rowsProcessed\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return final grid result                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": returnFinalResult ( s n# t | ec n# f .... nn t/f )\n"
    "\n"
    "  tp: returnFinalResult\n"
    "\n"
    "  0 0 0 0 locals| iNodeNumber iErrorCode results seitf |\n"
    "\n"
    "  // get this tasks seitf\n"
    "  task::this task.seitf@ to seitf\n"
    "\n"
    "  // was the final result true ?\n"
    "  true == if ( s n# t | ec n# f .... nn )\n"
    "\n"
    "     // drop the rest of the result\n"
    "     depth dropN ( )\n"
    "     true\n"
    "  else\n"
    "\n"
    "    // lets see which node failed\n"
    "    0 do  ( s n# t | ec n# f .... )\n"
    "\n"
    "    false == if ( s n# t | ec n# )\n"
    "\n"
    "      to iNodeNumber\n"
    "      to iErrorCode\n"
    "      iErrorCode error.msg\n"
    "      iNodeNumber grid::node node.name\n"
    "      \\\"error: %v %v\\\" str.format .\n"
    "      iErrorCode false\n"
    "    else\n"
    "      drop drop\n"
    "    then\n"
    "\n"
    "    loop\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print grid result                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": printFile ( NodeObject n# t | ec n# f .... nn t/f )\n"
    "\n"
    "  tp: printFile\n"
    "\n"
    "  // was the final result true ?\n"
    "  true == if ( s n# t | ec n# f .... nn )\n"
    "\n"
    "    // pretty print the results resturned\n"
    "    0 do  ( s n# t | s n# f .... )\n"
    "\n"
    "      assert // should be true\n"
    "      swap >object file.path@ swap\n"
    "      \\\"Node%v: %v\\\"  str.format .\n"
    "    loop\n"
    "\n"
    "  else\n"
    "\n"
    "    // lets see which node failed\n"
    "    0 do  ( s n# t | ec n# f .... )\n"
    "\n"
    "      false == if ( s n# t | ec n# )\n"
    "\n"
    "        swap error.msg swap\n"
    "        \\\"Node%v ERROR: %v\\\" str.format .\n"
    "\n"
    "      else\n"
    "\n"
    "        drop drop\n"
    "\n"
    "      then\n"
    "\n"
    "    loop\n"
    "\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* path for SE                                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\\\"../OS\\\\\\\\ X/Build/Products/Debug/SE\\\" constant SE_PATH\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form the shell command for spawning a node                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": se_command ( nodeName clusterString -- \\\"<command>\\\" )\n"
    "\n"
    "  locals| nodeName |\n"
    "  locals| clusterString |\n"
    "\n"
    "  to clusterString\n"
    "  to nodeName\n"
    "\n"
    "  //  \\\"nohup \\\"\n"
    "  \\\"\\\"\n"
    "  SE_PATH str.cat\n"
    "  \\\" --start \\\" str.cat\n"
    "  \\\" --size \\\" str.cat args.regionSize >str str.cat\n"
    "  //\\\" --commands /Users/alkayamarti/rapidsSE/rapidsse/Commands\\\" str.cat\n"
    "  \\\" --commands /Users/ray/Desktop/rapidsse/Commands\\\" str.cat\n"
    "  clusterString str.cat\n"
    "  \\\" --regionPrefix \\\" str.cat args.regionPrefix str.cat\n"
    "  \\\" --partitionsPerNode \\\" str.cat args.partitionsPerNode >str str.cat\n"
    "  \\\" --name  \\\" str.cat nodeName str.cat\n"
    "  //\\\" --partitionsPerNode \\\" str.cat grid::slots >str str.cat\n"
    "  args.tracepoint if \\\" --tracepoint \\\" str.cat then\n"
    "  args.verbose if \\\" --verbose \\\" str.cat then\n"
    "  args.dontFree if \\\" --dontFree \\\" str.cat then\n"
    "  args.freeRB if \\\" --freeRB \\\" str.cat then\n"
    "  args.metadata if \\\" --metadata \\\" str.cat then\n"
    "\n"
    "  \\\" &\\\" str.cat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn all other nodes for a grid on this machine                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnNodes ( -- )\n"
    "\n"
    "  // test for single node\n"
    "  grid::nodes 1 == if exit then\n"
    "\n"
    "  // form the --node parameter string\n"
    "  locals| clusterString |\n"
    "  locals| node |\n"
    "\n"
    "  \\\"\\\"\n"
    "\n"
    "  grid::nodes 0 do\n"
    "    I grid::node   ( node )\n"
    "      to node\n"
    "    node node.port\n"
    "    node node.IP\n"
    "    node node.name\n"
    "    \\\" --node %v %v %v \\\" str.format\n"
    "    str.cat\n"
    "  loop\n"
    "\n"
    "  to clusterString\n"
    "\n"
    "  // spawn all other nodes\n"
    "  grid::nodes 0 do\n"
    "\n"
    "    // skip this node\n"
    "    I grid::thisNode@ != if\n"
    "\n"
    "      // form the shell command to spawn node I\n"
    "      clusterString I grid::node node.name se_command\n"
    "\n"
    "      // print the shell command\n"
    "      dup .\n"
    "\n"
    "      // execute the shell command\n"
    "      shell.execute\n"
    "\n"
    "      // check result\n"
    "      not assert\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    "  //grid::thisNode@ grid::StartNode!\n"
    "  grid::StartNode@ \\\"Cluster Start node: %v\\\" str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set start node                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setStartNode ( -- )\n"
    "\n"
    "  // set this node as the grid start node\n"
    "  grid::thisNode@ grid::StartNode!\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT grid.sen"_Stz
  ;

