  // munge of dexPlanner.sen
  sDefinition =
    "\""
    "\\\"munged dexPlanner.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* dexPlanner.sen -- distributed export planner                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" dexPlanner.sen\\\" .verbose\n"
    "\n"
    "1 constant distDexPlan\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distributed export planner (initial, single node version)                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dexPlanner_singular ( catalogNm schemaNm tableNm fileNm -- dexPlan )\n"
    "\n"
    "  locals| fileNm tableNm schemaNm catalogNm |\n"
    "  0 locals| partitionId |\n"
    "\n"
    "  // create a distributed export plan\n"
    "  plan::new locals| dexPlan |\n"
    "\n"
    "  // synthesise any plan-level symbolic arguments into the lambda text of plan\n"
    "  tableNm   dexPlan ##: $$tableNm\n"
    "  schemaNm  dexPlan ##: $$schemaNm\n"
    "  catalogNm dexPlan ##: $$catalogNm\n"
    "  // nb: the above could have been a frame level, but left it as an example\n"
    "\n"
    "  \\\"triggerScanOp\\\" str.format dexPlan plan.opFrame++ drop\n"
    "\n"
    "  // create the named opFrames in plan and any fame-level symbolic arguments\n"
    "  grid::slots 0 do\n"
    "\n"
    "    I grid::toPartition to partitionid\n"
    "\n"
    "    // frame-level symbolic arguments for scanOp#I\n"
    "    partitionid \\\"scanOp#%v\\\" str.format dexPlan plan.opFrame++ drop\n"
    "      partitionid    dexPlan ##: $$partition   // partition\n"
    "      \\\"writeOp.task\\\" dexPlan ##: $$nextOp      // next op is writeOp\n"
    "      \\\"writeOp#\\\"     dexPlan ##: $$nextProfile // next profile is writeOp#\n"
    "  loop\n"
    "\n"
    "  \\\"writeOp#\\\" dexPlan plan.opFrame++ drop\n"
    "    // frame-level symbolic arguments\n"
    "    fileNm            dexPlan ##: $$fileNm      // file to be exported to\n"
    "    grid::slots        dexPlan ##: $$nStreams    // number of streams in pipeline\n"
    "    \\\"responseOp.task\\\" dexPlan ##: $$nextOp      // pipe to next operator\n"
    "    \\\"responseOp#\\\"     dexPlan ##: $$nextProfile // pipe to next profile\n"
    "\n"
    "  \\\"responseOp#\\\" dexPlan plan.opFrame++ drop\n"
    "    \\\"sinkOp.task\\\"     dexPlan ##: $$nextOp      // pipe to next operator\n"
    "    \\\"sinkOp#\\\"         dexPlan ##: $$nextProfile // pipe to next profile\n"
    "\n"
    "  \\\"sinkOp#\\\" dexPlan plan.opFrame++ drop\n"
    "\n"
    "  // finish planning\n"
    "  dexPlan plan.finished\n"
    "\n"
    "  // return dexPlan\n"
    "  dexPlan\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distributed export planner (multi-node version)                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dexPlanner_distributed ( catalogNm schemaNm tableNm fileNm -- dexPlan )\n"
    "\n"
    "  //\\\"dexPlanner_distributed\\\" .\n"
    "\n"
    "  locals| fileNm tableNm schemaNm catalogNm |\n"
    "\n"
    "  // create a distributed export plan\n"
    "  plan::new locals| dexPlan |\n"
    "  0 locals| partitionId |\n"
    "\n"
    "  // synthesise any plan-level symbolic arguments into the lambda text of plan\n"
    "  tableNm   dexPlan  ##: $$tableNm\n"
    "  schemaNm  dexPlan  ##: $$schemaNm\n"
    "  catalogNm dexPlan  ##: $$catalogNm\n"
    "  // nb: the above could have been a frame level, but left it as an example\n"
    "\n"
    "  //schemaNm .\n"
    "  \\\"triggerScanOp\\\" str.format dexPlan plan.opFrame++ drop\n"
    "\n"
    "  // create the named opFrames in plan and any fame-level symbolic arguments\n"
    "  grid::partitions 0 do\n"
    "\n"
    "    I to partitionid\n"
    "\n"
    "    // frame-level symbolic arguments for scanOp#I\n"
    "    partitionid \\\"scanOp#%v\\\" str.format dexPlan plan.opFrame++ drop\n"
    "      partitionid    dexPlan ##: $$partition   // partition\n"
    "      \\\"writeOp.task\\\" dexPlan ##: $$nextOp      // next op is writeOp\n"
    "      \\\"writeOp#\\\"     dexPlan ##: $$nextProfile // next profile is writeOp#\n"
    "  loop\n"
    "\n"
    "  \\\"writeOp#\\\" dexPlan plan.opFrame++ drop\n"
    "    // frame-level symbolic arguments\n"
    "    fileNm            dexPlan ##: $$fileNm      // file to be exported to\n"
    "    grid::partitions   dexPlan ##: $$nStreams    // number of streams in pipeline\n"
    "    \\\"responseOp.task\\\" dexPlan ##: $$nextOp      // pipe to next operator\n"
    "    \\\"responseOp#\\\"     dexPlan ##: $$nextProfile // pipe to next profile\n"
    "\n"
    "  \\\"responseOp#\\\" dexPlan plan.opFrame++ drop\n"
    "    \\\"sinkOp.task\\\"     dexPlan ##: $$nextOp      // pipe to next operator\n"
    "    \\\"sinkOp#\\\"         dexPlan ##: $$nextProfile // pipe to next profile\n"
    "\n"
    "  \\\"sinkOp#\\\" dexPlan plan.opFrame++ drop\n"
    "\n"
    "  // return dexPlan\n"
    "  dexPlan\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distributed export planner                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dexPlanner ( catalogNm schemaNm tableNm fileNm -- dexPlan )\n"
    "\n"
    "  distDexPlan if dexPlanner_distributed else dexPlanner_singular then\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT dexPlanner.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job_ListIndexes.sen
  sDefinition =
    "\""
    "\\\"munged job_ListIndexes.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_ListIndexes.sen -- Job list Indexes                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_ListIndexes.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list indexes of a table                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIndexes ( Job_ListIndexes -- )\n"
    "\n"
    "  params| pJob_ListIndexes |\n"
    "\n"
    "  0 0 0 0 locals| iCount pIndex iColumns pTable |\n"
    "\n"
    "  \\\"\\\"   // initial contents of the string\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                         // setup iteration of words\n"
    "\n"
    "    // get the index ptr\n"
    "    object@ word.name findInCurrent execute to pIndex\n"
    "\n"
    "    // skip hidden index\n"
    "    pIndex index.isHidden@ not if\n"
    "\n"
    "    // increment count\n"
    "    1 iCount + to iCount\n"
    "\n"
    "    // index a primary key ?\n"
    "    pIndex index.isPrimaryKey@\n"
    "    if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "    // index is unique ?\n"
    "    pIndex index.isUnique@\n"
    "    if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "      // add word kind to ls string\n"
    "      object@ word.name\n"
    "\n"
    "      \\\"row: ( '%v',%v,%v )\\\\n\\\" str.format\n"
    "      str.cat\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!       // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in the job\n"
    "  grid::thisNode@ pJob_ListIndexes job.response!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // sent rows Processed in the job\n"
    "  iCount grid::thisNode@ pJob_ListIndexes job.rowsProcessed!\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* List Indexes requests (on the originating node)                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIndexes_req ( -- <R> )\n"
    "\n"
    "  0 0 0 0 locals| sTableNm iCount pJob_ListIndexes pTask |\n"
    "\n"
    "  tp: listIndexes_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_ListIndexes\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // set dictionary stack\n"
    "  pJob_ListIndexes getPath\n"
    "  dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab ddl read lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if pJob_ListIndexes <ERROR_REQUEST> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get table name from job\n"
    "  pJob_ListIndexes job.objectName@ to sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if pJob_ListIndexes <ERROR_REQUEST> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is a table\n"
    "  sTableNm checkIsTableR35 not if popTable pJob_ListIndexes <ERROR_REQUEST> exit then\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(indexNo INTEGER, name VARCHAR, type VARCHAR, scale INTEGER, precision INTEGER, isUnique BOOLEAN, isPrimaryKey BOOLEAN)\\\"\n"
    "       pJob_ListIndexes job.metadata!\n"
    "  then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list table columns\n"
    "  pJob_ListIndexes listIndexes\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "  assertInTables\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_ListIndexes.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job_Sanity.sen
  sDefinition =
    "\""
    "\\\"munged job_Sanity.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Sanity.sen -- Job Sanity                                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Sanity.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to get sanity of nodes in the grid (on originating node)           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_req ( -- <R> )\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "  tp: space_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(nodeName VARCHAR, sanity VARCHAR)\\\"\n"
    "  pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_Sanity job                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_exe ( pJob_Sanity -- )\n"
    "\n"
    "  //params| pJob_Sanity |\n"
    "  job::this locals| pJob_Sanity |\n"
    "\n"
    "  0 0 locals| iSize iPartitions |\n"
    "\n"
    "  CN_JOB_SANITY pJob_Sanity object.assertClass\n"
    "\n"
    "  \\\"GETTING SANITY on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the node size of originating node from the job\n"
    "  pJob_Sanity job.regionSize@ to iSize\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the no of partitions of originating node from the job\n"
    "  pJob_Sanity job.partitions@ to iPartitions\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  args.tracepoint if\n"
    "    \\\"GETTING PARTITIONS on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  iPartitions node.partitions == not if\n"
    "    EC_CLUSTER_PARTITIONS_MISMATCH\n"
    "    grid::thisNode@ pJob_Sanity job.error!\n"
    "  else\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    args.tracepoint if\n"
    "      \\\"GETTING SIZE on NODE \\\"grid::thisNode@ >str str.cat .\n"
    "    then\n"
    "\n"
    "    iSize node.size == not if\n"
    "      EC_CLUSTER_SIZE_MISMATCH\n"
    "      grid::thisNode@ pJob_Sanity job.error!\n"
    "    else\n"
    "      \\\"row: ('\\\"\n"
    "      grid::thisNodeName@ str.cat\n"
    "       \\\"','sanity check passed')\\\" str.cat\n"
    "      grid::thisNode@ pJob_Sanity job.response!\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  pJob_Sanity job.notice\n"
    "\n"
    "  pJob_Sanity send_job__executed\n"
    "\n"
    "  nullptr task::this task.job!\n"
    "\n"
    "  <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity__beg ( -- )\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  pJob_sanity job.beginParticipant\n"
    "\n"
    "  job::participantBegun\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_end ( -- )\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  job::participantEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_can ( -- )\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  job::participantCancelled\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_Sanity.sen"_Stz
  ;

  vCompileConstant(sDefinition);

