  // munge of requests_tx.sen
  sDefinition =
    "\""
    "\\\"munged requests_tx.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_tx.sen -- the set of transaction related requests                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" requests_tx.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin a transaction                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": txBegin_req ( -- R )\n"
    "\n"
    "  //\\\"begin transaction\\\" .\n"
    "\n"
    "  tx::begin locals| pTx |\n"
    "\n"
    "  pTx task::this task.seitf@ seitf.tx!\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* commit a transaction                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": txCommit_req ( -- R )\n"
    "\n"
    "  //\\\"commit transaction\\\" .\n"
    "\n"
    "  task::this task.seitf@ seitf.tx@ locals| pTx |\n"
    "\n"
    "  pTx tx.commit\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end a transaction                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": txEnd_req ( -- R )\n"
    "\n"
    "  //\\\"end transaction\\\" .\n"
    "\n"
    "  task::this task.seitf@ seitf.tx@ locals| pTx |\n"
    "\n"
    "  pTx tx.free\n"
    "\n"
    "  nullPtr task::this task.seitf@ seitf.tx!\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* rollback a transaction                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": txRollback_req ( -- R )\n"
    "\n"
    "  task::this task.seitf@ seitf.tx@ locals| pTx |\n"
    "\n"
    "  pTx tx.rollback\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump all transactions on this node (run by participant)                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dump_all_tx allParticipants 0 checkResult ( -- true n# true )\n"
    "\n"
    "tp: dump_all_tx\n"
    "\n"
    "  args.tracepoint if\n"
    "    \\\"DUMPING TX'S on NODE \\\"grid::thisNodeName@ str.cat .\n"
    "  then\n"
    "\n"
    "  tx::dumpAll\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump all transactions in the grid                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": txDumpAll_req ( -- <R> )\n"
    "\n"
    "  \\\"dump all transactions\\\" .\n"
    "\n"
    "  dump_all_tx\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_tx.sen"_Stz
  ;

  vCompileConstant(sDefinition);

