  // munge of dic.sen
  sDefinition =
    "\""
    "\\\"munged dic.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* dic.sen -- dictionary related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" dic.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* folder is used as a kind of word to identify folders                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder ;\n"
    "\n"
    ": isFolder word.kind@ tick folder eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the tenant dictionary using name from input(doesnt leave dic on stk)*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicTenants:\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  createTenants\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dic allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIC word.this >body object.class!\n"
    "  tick folder word.this word.kind!\n"
    "  word.this >body dic.init\n"
    "  true word.this >body object.wordbody!\n"
    "\n"
    "  //word.this word.name \\\"  dic: %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a dictionary using name from input stream (doesnt leave dic on stk) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dic:\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dic allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIC word.this >body object.class!\n"
    "  tick folder word.this word.kind!\n"
    "  word.this >body dic.init\n"
    "  true word.this >body object.wordbody!\n"
    "\n"
    "  //word.this word.name \\\"  dic: %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    ": dicPersistent:\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  createPersistent\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dic allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIC word.this >body object.class!\n"
    "  tick folder word.this word.kind!\n"
    "  word.this >body dic.init\n"
    "  true word.this >body object.wordbody!\n"
    "\n"
    "  //word.this word.name \\\"  dic: %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a dictionary using name on the stack (leaves dic on stack)          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :dic\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dic allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIC word.this >body object.class!\n"
    "  tick folder word.this word.kind!\n"
    "  word.this >body dic.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "\n"
    "  //word.this word.name \\\"  :dic %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    ": :dicPersistent\n"
    "\n"
    "diclock.grabwrite\n"
    "\n"
    "  >createPersistent\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dic allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIC word.this >body object.class!\n"
    "  tick folder word.this word.kind!\n"
    "  word.this >body dic.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "\n"
    "  //word.this word.name \\\"  :dic %v\\\" str.format .\n"
    "\n"
    "diclock.dropwrite\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsDic ( word )\n"
    "\n"
    "  dup not if drop EC_NO_SUCH_FOLDER false exit then\n"
    "  dup word.kind@ tick folder eql if true exit then\n"
    "  drop\n"
    "  EC_NOT_A_FOLDER false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsDicR35 ( word )\n"
    "  params| pWord |\n"
    "\n"
    "  pWord not if EC_NO_SUCH_FOLDER false exit then\n"
    "  pWord word.kind@ tick folder eql if true exit then\n"
    "  EC_NOT_A_FOLDER false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicHasRef ( word )\n"
    "\n"
    "  dup execute dic.ref\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check dic not in use                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkNotUsed ( dic -- true | error false )\n"
    "\n"
    "  //dicHasRef \\\" dic ref \\\" .put .put .\\\\n\n"
    "\n"
    "  dicHasRef if EC_FOLDER_IN_USE false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check dic is empty                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsEmpty ( dic -- true | error false )\n"
    "\n"
    "  dup execute dic.wordCount if EC_FOLDER_NOT_EMPTY false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT dic.sen"_Stz
  ;

  vCompileConstant(sDefinition);

