    ": memoryStats ( -- )\n"
    "\n"
    "  memory::list\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted print                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fmt.print\n"
    "\n"
    "  str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted put                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fmt.put\n"
    "\n"
    "  str.format .put\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* stack should have zero values                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertStackDepthZero\n"
    "\n"
    "  depth 0 == if exit then\n"
    "\n"
    "  task::this task.name@ \\\"Stack of task %v has grown\\\" fmt.print\n"
    "\n"
    "  debug::trap\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT useful.sen"_Stz
  ;

