    "\n"
    "  args.metadata if\n"
    "    \\\"(columnName VARCHAR)\\\" pJob_ListPartColumns job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list partition columns\n"
    "  sTableNm pJob_ListPartColumns listPartitionColumns\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "  assertInTables\n"
    "\n"
    "  <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_ListPartColumns.sen"_Stz
  ;

