    "    << pSeitf partitionid \\\"scanOp#%v\\\" str.format thePlan plan.id@ \\\"scanOp.task\\\" >>jobQueue\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* triggerPlan_distributed                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": triggerScanPlan_distributed subDic triggerScan ( pSeitf profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile pSeitf |\n"
    "\n"
    "  //thePlan plan.id@ \\\"Triggering plan: %v\\\" str.format .\n"
    "\n"
    "  // trigger scanOp by piping the plan to it\n"
    "  grid::partitions 0 do\n"
    "\n"
    "  // << profile plan >> -->> nextOp\n"
    "  << pSeitf I \\\"scanOp#%v\\\" str.format thePlan plan.id@ \\\"scanOp.task\\\" >>jobQueue\n"
    "  //<< I \\\"rangeOp#%v\\\" str.format thePlan plan.id@ \\\"rangeOp.task\\\" >>jobQueue\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* flow trigger operator loop                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": triggerScanOp operator ( -- NEVER )\n"
    "\n"
    "  begin\n"
    "\n"
    "    depth 0 != if \\\"stack of task has grown\\\" . debug::trap then\n"
    "\n"
    "    // wait for next job\n"
    "    jobQueue> ( valset )\n"
    "\n"
    "    // unpack it\n"
    "    valset> ( nextOp profile planId nValues )\n"
    "    drop ( nextOp profile planId )\n"
    "    // find plan using planId\n"
    "    planList::findPlan ( pSeitf profile plan true )\n"
    "    assert ( pSeitf profile plan )\n"
    "\n"
    "    // trigger the plan\n"
    "    triggerScanPlan_distributed ( )\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT Op_triggerScan.sen"_Stz
  ;

