  // munge of requests_folder.sen
  sDefinition =
    "\""
    "\\\"munged requests_folder.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_folder.sen -- the set of folder related requests                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" requests_folder.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a folder                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeFolder allParticipants 1 checkResult ( \\\"<folderNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: removeFolder\n"
    "\n"
    "  :forget\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* change folder to given folder name                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": cf_req ( \\\"<sFolderNm>\\\" -- R )\n"
    "\n"
    "  locals| sFolderNm |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"..\\\" which will go up one folder\n"
    "\n"
    "  // pop up one folder, but not into tenants\n"
    "  sFolderNm \\\"..\\\" str.equal if\n"
    "    0 pathPick dic.name \\\"tenants\\\" str.equal not if pathDrop then\n"
    "    //\\\"After cf ..\\\" . PATHDUMP\n"
    "    <OK>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"~\\\" will pop folder path till it reaches /tenants\n"
    "\n"
    "  // pop up to tenants\n"
    "  sFolderNm \\\"~\\\" str.equal if\n"
    "    begin 0 pathPick dic.name \\\"tenants\\\" str.equal not while pathDrop repeat\n"
    "    //\\\"After cf ~\\\" . PATHDUMP\n"
    "    <OK>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"tenants\\\" will clear folder path and set to /tenants\n"
    "\n"
    "  // clear dic path and push tenants\n"
    "  sFolderNm \\\"tenants\\\" str.equal if\n"
    "    //begin 0 pathPick dic.name \\\"<main>\\\" str.equal not while pathDrop repeat\n"
    "    pathDropAll\n"
    "    //sFolderNm checkIsWord not if <NIP+ERROR> exit then\n"
    "    //execute pathPush\n"
    "    attachmap::tenants@ execute pathPush\n"
    "    //\\\"After cf tenants\\\" . PATHDUMP\n"
    "   <OK>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // otherwise we expect a name of a sub -folder to which we push path to\n"
    "\n"
    "  // push sub-folder\n"
    "  sFolderNm findInCurrent\n"
    "  checkIsDic not if <NIP+ERROR> exit then\n"
    "  execute pathPush\n"
    "  //\\\"After cf <dicNm>\\\" . PATHDUMP\n"
    "  <OK>\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable folder                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveFolder ( \\\"<folderNm>\\\" -- \\\"<folderNm>\\\" true | \\\"<folderNm>\\\" errorCode false )\n"
    "\n"
    "  dup ( \\\"<folderNm>\\\" \\\"<folderNm>\\\" )\n"
    "\n"
    "  checkIsWord     not if false exit then ( \\\"<folderNm>\\\" word )\n"
    "  checkIsEmpty    not if false exit then ( \\\"<folderNm>\\\" word )\n"
    "  checkNotUsed    not if false exit then ( \\\"<folderNm>\\\" word )\n"
    "\n"
    "  drop ( \\\"<folderNm>\\\" )\n"
    "\n"
    "  true ( \\\"<folderNm>\\\" true )\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a folder                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": remove_folder ( \\\"<folderNm>\\\" -- <R> )\n"
    "\n"
    "  tp: dropDic\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  checkRemoveFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  removeFolder ( ) assert::stack_0\n"
    "\n"
    "  tp: droppedDic\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folder contents                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": lf_req\n"
    "\n"
    "  0 locals| iCount |\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, type VARCHAR)\\\" metadata!\n"
    "    \\\"\\\"\n"
    "    0 pathPick dic.lastWord dup iterate\n"
    "    //dup str.length if \\\"\\\\n\\\" str.cat then\n"
    "    1 iCount + to iCount\n"
    "    \\\"row: ('\\\" str.cat\n"
    "\n"
    "    object@ word.name str.cat\n"
    "\n"
    "    \\\"', \\\" str.cat\n"
    "\n"
    "    object@ isTable if\n"
    "      \\\"'table'\\\" str.cat\n"
    "      //object@ execute table.space bytes.magnitude str.cat\n"
    "    then\n"
    "\n"
    "    object@ isIndex if\n"
    "      \\\"'index'\\\" str.cat\n"
    "      //object@ execute table.space bytes.magnitude str.cat\n"
    "    then\n"
    "\n"
    "    object@ isFolder if\n"
    "      \\\"'\\\" str.cat\n"
    "      object@ execute dic.kind@ word.name str.cat\n"
    "      \\\"'\\\" str.cat\n"
    "    then\n"
    "\n"
    "    iCount if\n"
    "      \\\")\\\\n\\\" str.cat\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!\n"
    "\n"
    "    next\n"
    "    iCount task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"\\\"\n"
    "    0 pathPick dic.lastWord dup iterate\n"
    "\n"
    "      dup str.length if \\\"\\\\n\\\" str.cat then\n"
    "\n"
    "      object@ word.name 12 str.pad str.cat\n"
    "      1 iCount + to iCount\n"
    "      \\\"(\\\" str.cat\n"
    "\n"
    "      object@ isTable if\n"
    "        \\\"table \\\" str.cat\n"
    "        //object@ execute table.space bytes.magnitude str.cat\n"
    "      then\n"
    "\n"
    "      object@ isIndex if\n"
    "        \\\"index\\\" str.cat\n"
    "        //object@ execute table.space bytes.magnitude str.cat\n"
    "      then\n"
    "\n"
    "      object@ isFolder if\n"
    "        object@ execute dic.kind@ word.name str.cat\n"
    "      then\n"
    "\n"
    "      object@ word.prev object!\n"
    "      \\\")\\\" str.cat\n"
    "    next\n"
    "\n"
    "  then\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print working folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": pwf_req ( - sPath <SUCCESS> )\n"
    "\n"
    "  // test if we need to produce meta data\n"
    "  args.metadata if\n"
    "    \n"
    "    // set meta data information\n"
    "    \\\"(path VARCHAR)\\\" metadata!\n"
    "\n"
    "    // start of working string\n"
    "    \\\"row: ('/\\\"\n"
    "\n"
    "    // iterate thru each folder in path\n"
    "    pathDepth 0 do\n"
    "      // compute the path subscript\n"
    "      pathDepth 1 - I -\n"
    "      // pick the path, get its name and concat name to working string\n"
    "      pathPick dic.name str.cat\n"
    "      // concat \\\"/\\\" to end of working string\n"
    "      \\\"/\\\" str.cat\n"
    "    loop\n"
    "\n"
    "    // end working string\n"
    "    \\\"')\\\\n\\\" str.cat\n"
    "\n"
    "    // set number of rows processed\n"
    "    1 task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  else\n"
    "\n"
    "    // start of working string\n"
    "    \\\"/\\\"\n"
    "\n"
    "    // iterate thru each folder in path and concat to end\n"
    "    pathDepth 0 do\n"
    "      // compute the path subscript\n"
    "      pathDepth 1 - I -\n"
    "      // pick the path, get its name and concat name to working string\n"
    "      pathPick dic.name str.cat\n"
    "      // concat \\\"/\\\" to end of working string\n"
    "      \\\"/\\\" str.cat\n"
    "    loop\n"
    "\n"
    "  then\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "*/\n"
    "/////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create /tenants/boray/catalogs/rapidsse                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createDefaultFolders localCalls ( )\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  // push tenants folder\n"
    "  //\\\"tenants\\\" find execute\n"
    "  attachmap::tenants@ execute\n"
    "  pathPush\n"
    "\n"
    "    // create tenant boray (and catalogs sub-folder)\n"
    "    \\\"boray\\\" \\\"makeTenant\\\" find execute\n"
    "\n"
    "    // push boray folder\n"
    "    \\\"boray\\\" findInCurrent execute\n"
    "    pathPush\n"
    "\n"
    "      // push catalogs folder\n"
    "      \\\"catalogs\\\" findInCurrent execute\n"
    "      pathPush\n"
    "\n"
    "        // create catalog rapidsse (and schemas sub-folder)\n"
    "        \\\"rapidsse\\\" \\\"makeCatalog\\\" find execute\n"
    "\n"
    "          // push rapidsse folder\n"
    "          \\\"rapidsse\\\" findInCurrent execute\n"
    "          pathPush\n"
    "\n"
    "          // push schemas folder\n"
    "          \\\"schemas\\\" findInCurrent execute\n"
    "          pathPush\n"
    "\n"
    "          // create schema public (and tables sub-folder)\n"
    "          \\\"public\\\" \\\"makeSchema\\\" find execute\n"
    "\n"
    "          pathDrop\n"
    "      pathDrop\n"
    "    pathDrop\n"
    "  pathDrop\n"
    "\n"
    "  assert::stack_0\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_folder.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of miscTesting.sen
  sDefinition =
    "\""
    "\\\"munged miscTesting.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* miscTesting.sen -- miscellaneous testing                                   */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" miscTesting.sen\\\" .verbose\n"
    "\n"
    ": iftest if \\\"yes\\\" . then ;\n"
    "\n"
    ": ifelsetest if \\\"yes\\\" . else \\\"no\\\" . then ;\n"
    "\n"
    ": untiltest 0 begin 1 + dup . dup 10 == until ;\n"
    "\n"
    ": whiletest 0 begin 1 + dup 10 < while dup . repeat ;\n"
    "\n"
    ": dotest 10 0 do I . loop ;\n"
    ": ?dotest 10 0 ?do I . loop 10 10 ?do I . loop ;\n"
    "\n"
    ": +looptest 10 0 do I . 2 +loop ;\n"
    "\n"
    ": iterateTest\n"
    "    word.this word.this iterate // iterate word cursor\n"
    "      object@ word.name .       // print the name of the word\n"
    "      object@ word.prev object! // step backwards thru words\n"
    "    next                        // next iteration\n"
    " ;\n"
    "\n"
    ": string_blowup\n"
    "\n"
    "traceon\n"
    "    \\\"abcdefghijklmnopqrstuvwxyz\\\"\n"
    "    1000000 0 do\n"
    "      \\\"abcdefghijklmnopqrstuvwxyz\\\"\n"
    "      str.cat\n"
    "    loop\n"
    " ;\n"
    "\n"
    "str: strvar\n"
    "\n"
    ": strvar_blowup\n"
    "\n"
    "\n"
    "traceon\n"
    "\n"
    "  \\\"a\\\" strvar !\n"
    "  1000000 0 do\n"
    "    strvar @ \\\"a\\\" str.cat strvar !\n"
    "  loop\n"
    "\n"
    " ;\n"
    "\n"
    ": rottest\n"
    "\n"
    "  2 1 0 rot . . .\n"
    " ;\n"
    "\n"
    ": invrottest\n"
    "\n"
    "  2 1 0 -rot . . .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* globals testing                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": globalsTest\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  2048 str.random 1 >valset\n"
    "\n"
    "  >reg0\n"
    "\n"
    "  reg0\n"
    "\n"
    "  valset>\n"
    "\n"
    "  . .\n"
    "\n"
    "  reg.pop\n"
    " ;\n"
    "\n"
    ": globalsTest2\n"
    "\n"
    "//traceon\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  // create a vector of the CN_ enums\n"
    "  // currently thats ( -- 91 .. 0 92 )\n"
    "  1 neg CN_ENUMS 1- ?do I 1 neg +loop CN_ENUMS\n"
    "\n"
    "  // show the stack\n"
    "  //stk\n"
    "\n"
    "  // convert to valset\n"
    "  >valset\n"
    "\n"
    "  // put into reg0\n"
    "  >reg0\n"
    "\n"
    "  // copy into reg1\n"
    "  reg0 >reg1\n"
    "\n"
    "  // copy back to stack\n"
    "  reg1 //dup drop\n"
    "\n"
    "  // expand valset into vector\n"
    "  valset>\n"
    "\n"
    "  // show the stack\n"
    "  stk\n"
    "\n"
    "  reg.pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* str.format testing                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": strFormatTest\n"
    "\n"
    "  1 \\\"abc%v\\\" str.format .\n"
    "\n"
    "  \\\"def\\\" \\\"abc%v\\\" str.format .\n"
    "\n"
    "  \\\"gh\\\" 456 \\\"def\\\" 23 \\\"abc\\\" 1\n"
    "  \\\"%v %v %v %v %v %v\\\" str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* locals testing                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lt\n"
    "\n"
    "  789 456 123 locals| a b c |\n"
    "\n"
    "  a . b . c .\n"
    "\n"
    "  321 to a\n"
    "  654 to b\n"
    "  789 to c \n"
    "\n"
    "  a . b . c .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* postpone testing                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": callTest immediate\n"
    "\n"
    "  test\n"
    " ;\n"
    "\n"
    ": postponeTest\n"
    "\n"
    "  postpone callTest\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get a snapshot of the buffer pool objects                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": snapshot (  )\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  bp::snapshot ( int int .... #classes )\n"
    "\n"
    "  >valset\n"
    "  >reg0\n"
    "\n"
    "  \\\"First Snapshot...\\\" .\n"
    "  reg0\n"
    "  valset>\n"
    "  0 do\n"
    "    I class::name\n"
    "    \\\"%v %v\\\" str.format .\n"
    "  loop\n"
    "\n"
    "  bp::snapshot ( int int .... #classes )\n"
    "\n"
    "  >valset\n"
    "  >reg1\n"
    "\n"
    "  \\\"Second Snapshot...\\\" .\n"
    "  reg1\n"
    "  valset>\n"
    "  0 do\n"
    "    I class::name\n"
    "   \\\"%v %v\\\" str.format .\n"
    "  loop\n"
    "\n"
    "  reg1 reg0 vector.diff\n"
    "\n"
    "  \\\"Differnce of Snapshots...\\\" .\n"
    "  0 do\n"
    "    I class::name\n"
    "    \\\"%v %v\\\" str.format .\n"
    "  loop\n"
    "\n"
    "  reg.pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* string replacement                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": srepl\n"
    "\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthisdef\\\" str.replace .\n"
    "\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthidef\\\" str.replace .\n"
    "\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthisdefthis\\\" str.replace .\n"
    "  \\\"this\\\" \\\"that\\\" \\\"abcthisthisdefthis\\\" str.replace .\n"
    "  \\\"this\\\" \\\"that\\\" \\\"thisthiabcthisthisdefthis\\\" str.replace .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* plan list testing                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pl_test\n"
    "\n"
    "  plan::new locals| plan |\n"
    "\n"
    "  \\\"plan#1\\\" plan plan.name!\n"
    "\n"
    "  plan plan.show\n"
    "\n"
    "  plan stk >binval stk >object stk drop\n"
    "\n"
    "  plan planList::addPlan\n"
    "\n"
    "  planList::show\n"
    "\n"
    "  plan planList::removePlan\n"
    "\n"
    "  planList::show\n"
    "\n"
    "  plan::new planList::addPlan\n"
    "  plan::new planList::addPlan\n"
    "  plan::new planList::addPlan\n"
    "\n"
    "  planList::show\n"
    "\n"
    "  1 planList::findPlan .\n"
    "\n"
    "  3 planList::findPlan . .\n"
    "\n"
    "3 planList::findPlan if planList::removePlan then planList::show\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": whereAmI\n"
    "\n"
    "  \\\"whereAmI?\\\" .\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* group by testing                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": gby\n"
    "\n"
    "  groupBy::new locals| pGroupBy |\n"
    "\n"
    "  pGroupBy groupby.start\n"
    "  pGroupBy groupby.applyBuffer\n"
    "  pGroupBy groupby.end\n"
    "  pGroupBy groupby.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* steps                                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": stepsReset\n"
    "  steps::reset\n"
    " ;\n"
    "\n"
    ": stepsList\n"
    "  steps::list\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* locks                                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": locksReset\n"
    "  locks::reset\n"
    " ;\n"
    "\n"
    ": locksList\n"
    "  locks::list\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* memory                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": memoryReset\n"
    "  memory::reset\n"
    " ;\n"
    "\n"
    ": memoryList\n"
    "  memory::list\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* yield testing                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": yieldTest\n"
    "\n"
    "  10 0 do\n"
    "    I .\n"
    "    task.yield\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT miscTesting.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of actorPrimitives.sen
  sDefinition =
    "\""
    "\\\"munged actorPrimitives.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* actorPrimitives.sen -- actor primitives                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" actorPrimitives.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* task and queue arrays                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "grid::nodes ptrArray: ppTasks\n"
    "grid::nodes ptrArray: cpTasks\n"
    "grid::nodes ptrArray: pTasks\n"
    "grid::nodes ptrArray: senderTasks\n"
    "\n"
    "grid::nodes ptrArray: ppQueues\n"
    "grid::nodes ptrArray: cpQueues\n"
    "grid::nodes ptrArray: pQueues\n"
    "grid::nodes ptrArray: senderQueues\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the ppQueues array                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ppQueuesDump\n"
    "\n"
    "  \\\"{ \\\" .put\n"
    "  grid::nodes 0 do\n"
    "    I ppQueues @ .put \\\" \\\" .put\n"
    "  loop\n"
    "\n"
    "  \\\"}\\\" .put .\\\\n\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the cpQueues array                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": cpQueuesDump\n"
    "\n"
    "  \\\"{ \\\" .put\n"
    "  grid::nodes 0 do\n"
    "    I cpQueues @ .put \\\" \\\" .put\n"
    "  loop\n"
    "\n"
    "  \\\"}\\\" .put .\\\\n\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the pQueues array                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pQueuesDump\n"
    "\n"
    "  \\\"{ \\\" .put\n"
    "  grid::nodes 0 do\n"
    "    I pQueues @ .put \\\" \\\" .put\n"
    "  loop\n"
    "\n"
    "  \\\"}\\\" .put .\\\\n\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the senderQueues array                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": senderQDump\n"
    "\n"
    "  \\\"{ \\\" .put\n"
    "  grid::nodes 0 do\n"
    "    I senderQueues tp: @ .put \\\" \\\" .put\n"
    "  loop\n"
    "\n"
    "  \\\"}\\\" .put .\\\\n\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* append valset onto queue of given task and signal if its waiting           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >jobQueue ( valset task -- )\n"
    "\n"
    "tp: >jobQueue\n"
    "\n"
    "  locals| pTargetTask | ( valset )\n"
    "\n"
    "  // grab mutex of target task\n"
    "  pTargetTask grabMutex ( valset )\n"
    "\n"
    "  // append valset onto queue of target task\n"
    "  pTargetTask appendJobQueue ( )\n"
    "\n"
    "  // signal the target task if it is waiting for a valset to be queued\n"
    "  pTargetTask isSignalWaiting if\n"
    "    pTargetTask signal ( )\n"
    "  then\n"
    "\n"
    "  // drop mutex of target task\n"
    "  pTargetTask dropMutex ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* append indirect call onto queue of given task, wait for ack, move a to p   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >jobQueue;a> ( <<call>> task -- <<result>> )\n"
    "\n"
    "  // set this task to wait for 1 ack\n"
    "  1 setAcks ( <<call>> task )\n"
    "\n"
    "  // append indirect call onto queue of given task\n"
    "  >jobQueue ( )\n"
    "\n"
    "  tp: ackWait\n"
    "\n"
    "  // this task waits till ack'd\n"
    "  ackWait ( )\n"
    "\n"
    "  tp: running\n"
    "\n"
    "  // move indirect result from aux to data stack\n"
    "  a> ( <<result>> )\n"
    "\n"
    "tp: haveResultSet\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put indirect call onto queue of sender task                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >sendQueue ( <<call>> nodeNo -- )\n"
    "\n"
    "  // get sender task\n"
    "  senderTasks @ ( <<call>> task )\n"
    "\n"
    "  tp: sendingViaTask\n"
    "\n"
    "  // enqueue valset onto queue of task\n"
    "  >jobQueue ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put indirect call onto queue of sender task, suspend, move from a to p     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >sendQueue;a> ( <<call>> nodeNo -- )\n"
    "\n"
    "  // this task to wait for 1 ack\n"
    "  1 setAcks ( ... wordName #values queue )\n"
    "\n"
    "  // get sender task\n"
    "  senderTasks @ ( <<call>> task )\n"
    "\n"
    "tp: sendingViaTask\n"
    "\n"
    "  // enqueue valset onto queue of task\n"
    "  >jobQueue\n"
    "\n"
    "  // this task waits till ack'd\n"
    "  ackWait ( )\n"
    "\n"
    "tp: running\n"
    "\n"
    "  // move indirect result from aux to data stack \n"
    "  a> ( <<result>> )\n"
    "\n"
    "tp: haveResultSet\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop valset from this tasks job queue (this is a blocking call)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": jobQueue> ( -- valset )\n"
    "\n"
    "  tp: jobQueue>\n"
    "\n"
    "  // grab mutex of this task\n"
    "  task::this grabMutex\n"
    "\n"
    "  // attempt to pop from this task's job queue\n"
    "  popJobQueue ( value true | false )\n"
    "  not if\n"
    "    // queue empty; wait till signalled\n"
    "    signalWait\n"
    "    // pop from this tasks job queue\n"
    "    popJobQueue assert\n"
    "  then\n"
    "\n"
    "  // grab mutex of this task\n"
    "  task::this dropMutex\n"
    "\n"
    "  tp: haveValset\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* push indirect result onto callers aux stack and ack caller                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >callerAux ( <<result>> -- )\n"
    "\n"
    "tp: >callerAux\n"
    "\n"
    "  // transfer to callers stack\n"
    "  _CALLER ( <<result>> callingTask )\n"
    "\n"
    "  tp: callingTask\n"
    "\n"
    "  >auxStack ( )\n"
    "\n"
    "  // ack caller\n"
    "  _CALLER ack ( )\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set the calling task                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setCaller ( caller -- ; reg0 == caller )\n"
    "\n"
    "  to_CALLER ( )\n"
    "\n"
    "  tp: reg0HasCaller\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set sending node                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setSender ( sender -- ; reg4 == sender )\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pass indirect call onto coordinator proxy                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": passOnToCP ( valset nodeNo -- )\n"
    "\n"
    "  cpTasks @ ( valset task )\n"
    "\n"
    "  >jobQueue ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pass indirect result back to participant proxy                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": passBackToPP ( <<result>> nodeName -- )\n"
    "\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute indirect call on the stack                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": !indirect ( ... wordName -- ... )\n"
    "\n"
    "tp: executing...\n"
    "\n"
    "  // find the word in dic stack\n"
    "  find ( word )\n"
    "                                                          //! WHAT IF NOT FOUND?\n"
    "\n"
    "  // execute it\n"
    "  execute ( ... )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* convert all values on stack into a result valset                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >result ( ... -- valset )\n"
    "\n"
    "tp: resultIs\n"
    "\n"
    "  // put number of values onto stack\n"
    "  depth ( ... #values )\n"
    "\n"
    "  // convert to valset\n"
    "  >valset ( valset )\n"
    "\n"
    "tp: resultAsValset\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* expand valset and execute indirect call                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": exeOne ( <<call*>> )\n"
    "\n"
    "  valset> ( ... wordName nValues )\n"
    "\n"
    "  drop ( ... wordName )\n"
    "\n"
    "  tp: callSetUp\n"
    "\n"
    "  !indirect ( bool )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute all nested valsets                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": exeAll ( ... valset -- x )\n"
    "\n"
    "tp: exeAll\n"
    "\n"
    "  // we exect at least one indirect\n"
    "  CN_VALSET isType not if assert then\n"
    "\n"
    "  // execute first indirect\n"
    "  exeOne\n"
    "\n"
    "  // execute all other indirects\n"
    "  begin\n"
    "\n"
    "    // no more to execute?\n"
    "    CN_VALSET isType not\n"
    "    if\n"
    "      exit\n"
    "    then\n"
    "\n"
    "  // execute next indirect\n"
    "  exeOne\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to send to one participant                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addSendParticipant ( valset node -- valset )\n"
    "\n"
    "  \\\"sendParticipant\\\" ( valset node \\\"sendParticipant\\\" )\n"
    "\n"
    "tp: addingSendP\n"
    "\n"
    "  >> ( valset )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to send to all participants                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addSendParticipants ( valset -- valset )\n"
    "\n"
    "  \\\"sendParticipants\\\" ( valset \\\"sendParticipants\\\" )\n"
    "\n"
    "tp: addingSendPs\n"
    "\n"
    "  >> ( valset )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to set caller                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addSetCaller ( valset -- valset )\n"
    "\n"
    "  task::this \\\"setCaller\\\"\n"
    "\n"
    "tp: addingSetCaller\n"
    "\n"
    "  >>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to set dic path                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addSetDicStack ( valset -- valset )\n"
    "\n"
    "  // add dicStack.set indirect\n"
    "  pathGet ( valset path... #folders )\n"
    "  \\\"dicStack.set\\\" ( valset path... #folders \\\"dicStack.set\\\" )\n"
    "\n"
    "tp: addingSetDicStack\n"
    "\n"
    "  >> ( valset )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to set sender                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addSetSender ( valset -- valset )\n"
    "\n"
    "  grid::thisNodeName@ \\\"setSender\\\"\n"
    "\n"
    "tp: addingSetSender\n"
    "\n"
    "  >>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to pass result back to participant proxy                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addPassBackToPP ( valset -- valset )\n"
    "\n"
    "  grid::thisNodeName@ \\\"passBackToPP\\\"\n"
    "\n"
    "  tp: addingPassBackToPP\n"
    "\n"
    "  >>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to pass call onto coordinator proxy                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addPassOnToCP ( valset -- valset )\n"
    "\n"
    "  \\\"passOnToCP\\\"\n"
    "\n"
    "tp: addingPassOnToCP\n"
    "\n"
    "  >>\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT actorPrimitives.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job__End.sen
  sDefinition =
    "\""
    "\\\"munged job__End.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__End.sen -- generic job related words                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__End.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute Job__End to all participants                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__End::distribute ( pJobOriginator -- )\n"
    "\n"
    "  //\n"
    "  // where:  On the originator node.\n"
    "  //\n"
    "\n"
    "  params| pJobOriginator |\n"
    "\n"
    "  0 locals| pJob__End |\n"
    "\n"
    "  // set the no of acks expected in originator job\n"
    "  grid::nodes pJobOriginator job.acksRemaining!\n"
    "\n"
    "  // new a temporary Job__End\n"
    "  pJobOriginator job.id@ job.newEnd to pJob__End\n"
    "\n"
    "  // send Job__End to all nodes\n"
    "  grid::nodes 0\n"
    "  do\n"
    "    // set which node this task will to send to\n"
    "    I grid::node task::this task.sendNode!\n"
    "\n"
    "    // move this task through send state/queue\n"
    "    task.send\n"
    "\n"
    "    // send the end job\n"
    "    pJob__End >socket\n"
    "  loop\n"
    "\n"
    "  // now delete the end job\n"
    "  pJob__End job.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__End on participating node                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__End_rcv ( -- )\n"
    "\n"
    "  //\n"
    "  // where: on the participating node\n"
    "  //\n"
    "\n"
    "  job::this locals| pJob__End |\n"
    "\n"
    "  // find the job to be executed in the participating jobs\n"
    "  pJob__End job.id@ locals| iJobId |\n"
    "  iJobId job.findParticipant locals| pJobParticipant |\n"
    "\n"
    "  // execute the end seed of the job on this participating node\n"
    "  pJobParticipant SEED_END job.spawn\n"
    "\n"
    "  delete_completed_job\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__End.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of file.sen
  sDefinition =
    "\""
    "\\\"munged file.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* file.sen -- file related words                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" file.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* file is use as a kind of word to identify files                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": file ;\n"
    "\n"
    ": isFile word.kind@ tick file eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a file using name from input stream (doesnt leave file on stk)      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": file:\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_file allot\n"
    "  word.this >body object.magic!\n"
    "  CN_FILE word.this >body object.class!\n"
    "  tick file word.this word.kind!\n"
    "  word.this >body file.init\n"
    "  true word.this >body object.wordbody!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a file using name on stack (leaves file on stack)                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :file\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_file allot\n"
    "  word.this >body object.magic!\n"
    "  CN_FILE word.this >body object.class!\n"
    "  tick file word.this word.kind!\n"
    "  word.this >body file.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* load contents of named file onto stack                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fileLoad ( \\\"<fileNm>\\\" -- s true | false )\n"
    "\n"
    "  file::new locals| loadFile |\n"
    "\n"
    "  loadFile file.path!\n"
    "\n"
    "  OPEN_READ loadFile file.open\n"
    "  not if\n"
    "    loadFile file.path@ \\\"No such file %v\\\" str.format .\n"
    "    loadFile file.delete\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  \\\"\\\"\n"
    "  begin loadFile file.read while\n"
    "    str.cat \\\" \\\" str.cat\n"
    "  repeat\n"
    "\n"
    "  loadFile file.delete\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT file.sen"_Stz
  ;

  vCompileConstant(sDefinition);

